const STALE_LAZY_IMPORT_PATTERNS = [
  /ChunkLoadError/i,
  /error loading dynamically imported module/i,
  /Failed to fetch dynamically imported module/i,
  /Importing a module script failed/i,
];

const RELOAD_KEY_PREFIX = "atomic-crm:lazy-import-reload:";

const getErrorMessage = (error: unknown) => {
  if (error instanceof Error) {
    return error.message;
  }

  return typeof error === "string" ? error : "";
};

export const isStaleLazyImportError = (error: unknown) => {
  const message = getErrorMessage(error);

  return STALE_LAZY_IMPORT_PATTERNS.some((pattern) => pattern.test(message));
};

const getReloadKey = (key: string) => `${RELOAD_KEY_PREFIX}${key}`;

const readReloadFlag = (key: string) => {
  try {
    return window.sessionStorage.getItem(getReloadKey(key)) === "true";
  } catch {
    return false;
  }
};

const writeReloadFlag = (key: string, value: boolean) => {
  try {
    if (value) {
      window.sessionStorage.setItem(getReloadKey(key), "true");
    } else {
      window.sessionStorage.removeItem(getReloadKey(key));
    }
  } catch {
    // Ignore storage failures and fall back to normal error handling.
  }
};

export const performPageReload = () => {
  window.location.reload();
};

export const lazyImportWithReload = <TModule>(
  importer: () => Promise<TModule>,
  key: string,
  reload: () => void = performPageReload,
) => {
  return async () => {
    try {
      const module = await importer();
      if (typeof window !== "undefined") {
        writeReloadFlag(key, false);
      }
      return module;
    } catch (error) {
      if (
        typeof window !== "undefined" &&
        isStaleLazyImportError(error) &&
        !readReloadFlag(key)
      ) {
        writeReloadFlag(key, true);
        reload();
        return new Promise<never>(() => {});
      }

      if (typeof window !== "undefined") {
        writeReloadFlag(key, false);
      }

      throw error;
    }
  };
};
