import { memo } from "react";
import { useRecordContext } from "ra-core";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";

import type { Company } from "../types";

// Memoized inner component to prevent re-renders when avatar src hasn't changed
const CompanyAvatarInner = memo(
  ({
    src,
    name,
    sizeClass,
    fallbackClass,
  }: {
    src?: string;
    name: string;
    sizeClass: string;
    fallbackClass: string;
  }) => (
    <Avatar className={sizeClass}>
      <AvatarImage src={src} alt={name} className="object-contain" />
      <AvatarFallback className={fallbackClass}>
        {name.charAt(0)}
      </AvatarFallback>
    </Avatar>
  ),
  (prev, next) => prev.src === next.src && prev.name === next.name,
);

CompanyAvatarInner.displayName = "CompanyAvatarInner";

export const CompanyAvatar = (props: {
  record?: Company;
  width?: 20 | 40;
  height?: 20 | 40;
}) => {
  const { width = 40 } = props;
  const record = useRecordContext<Company>(props);
  if (!record) return null;

  const sizeClass = width !== 40 ? `w-[20px] h-[20px]` : "w-10 h-10";
  const fallbackClass = width !== 40 ? "text-xs" : "text-sm";

  return (
    <CompanyAvatarInner
      src={record.logo?.src}
      name={record.name}
      sizeClass={sizeClass}
      fallbackClass={fallbackClass}
    />
  );
};
