import { CheckCircle2, Circle, Pencil } from "lucide-react";
import {
  useListContext,
  useUpdate,
  useNotify,
  RecordContextProvider,
} from "ra-core";
import { format } from "date-fns";
import { useMemo, useState } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { DeleteButton } from "@/components/admin/delete-button";

import { ListingMilestoneCreate } from "./ListingMilestoneCreate";
import { AddSectionContainer } from "../misc/AddSectionContainer";
import type { ListingMilestone } from "../types";

export const SmartTimelineIterator = () => {
  const { data: milestones, isPending } = useListContext<ListingMilestone>();
  const [update] = useUpdate();

  const { incomplete, completed } = useMemo(() => {
    if (!milestones) return { incomplete: [], completed: [] };
    const inc = milestones
      .filter((m) => !m.is_completed)
      .sort((a, b) => (a.id as number) - (b.id as number));
    const comp = milestones
      .filter((m) => m.is_completed)
      .sort((a, b) => {
        const dateA = a.completion_date
          ? new Date(a.completion_date).getTime()
          : 0;
        const dateB = b.completion_date
          ? new Date(b.completion_date).getTime()
          : 0;
        return dateB - dateA;
      });
    return { incomplete: inc, completed: comp };
  }, [milestones]);

  if (isPending || !milestones) return null;

  const toggleMilestone = (milestone: ListingMilestone) => {
    update("listing_milestones", {
      id: milestone.id,
      data: {
        is_completed: !milestone.is_completed,
        completion_date: !milestone.is_completed
          ? new Date().toISOString()
          : undefined,
      },
      previousData: milestone,
    });
  };

  const updateCompletionDate = (
    milestone: ListingMilestone,
    newDate: string,
  ) => {
    update("listing_milestones", {
      id: milestone.id,
      data: { completion_date: new Date(newDate).toISOString() },
      previousData: milestone,
    });
  };

  return (
    <div className="pt-4 flex flex-col gap-4">
      <AddSectionContainer label="Add milestones" defaultOpen={false}>
        <ListingMilestoneCreate />
      </AddSectionContainer>
      {milestones.length === 0 && (
        <p className="text-sm text-muted-foreground pt-4">No milestones yet.</p>
      )}
      {incomplete.map((milestone) => (
        <MilestoneRow
          key={milestone.id}
          milestone={milestone}
          onToggle={toggleMilestone}
          onDateChange={updateCompletionDate}
        />
      ))}
      {incomplete.length > 0 && completed.length > 0 && (
        <div className="border-t my-2 pt-2 text-xs text-muted-foreground uppercase tracking-wider">
          Completed
        </div>
      )}
      {completed.map((milestone) => (
        <MilestoneRow
          key={milestone.id}
          milestone={milestone}
          onToggle={toggleMilestone}
          onDateChange={updateCompletionDate}
        />
      ))}
    </div>
  );
};

const MilestoneRow = ({
  milestone,
  onToggle,
  onDateChange,
}: {
  milestone: ListingMilestone;
  onToggle: (m: ListingMilestone) => void;
  onDateChange: (m: ListingMilestone, newDate: string) => void;
}) => {
  const [editingDate, setEditingDate] = useState(false);
  const [editing, setEditing] = useState(false);
  const [editName, setEditName] = useState(milestone.milestone_name);
  const [editNotes, setEditNotes] = useState(milestone.notes ?? "");
  const [update] = useUpdate();
  const notify = useNotify();

  const handleSave = () => {
    const trimmedName = editName.trim();
    if (!trimmedName) return;
    update(
      "listing_milestones",
      {
        id: milestone.id,
        data: {
          milestone_name: trimmedName,
          notes: editNotes.trim() || undefined,
        },
        previousData: milestone,
      },
      {
        onSuccess: () => {
          setEditing(false);
          notify("Milestone updated");
        },
      },
    );
  };

  const handleCancel = () => {
    setEditName(milestone.milestone_name);
    setEditNotes(milestone.notes ?? "");
    setEditing(false);
  };

  if (editing) {
    return (
      <div className="p-3 border rounded-lg space-y-2 bg-muted/30">
        <Input
          value={editName}
          onChange={(e) => setEditName(e.target.value)}
          placeholder="Milestone name"
          className="text-sm"
          autoFocus
        />
        <Textarea
          value={editNotes}
          onChange={(e) => setEditNotes(e.target.value)}
          placeholder="Notes (optional)"
          className="text-sm min-h-[60px]"
        />
        <div className="flex justify-end gap-2">
          <Button
            variant="ghost"
            size="sm"
            type="button"
            onClick={handleCancel}
          >
            Cancel
          </Button>
          <Button
            size="sm"
            type="button"
            disabled={!editName.trim()}
            onClick={handleSave}
          >
            Save
          </Button>
        </div>
      </div>
    );
  }

  return (
    <div className="relative flex items-start gap-4 p-2 hover:bg-muted/50 rounded-lg transition-colors group">
      <Button
        variant="ghost"
        size="icon"
        className="mt-0.5 shrink-0 h-6 w-6"
        onClick={() => onToggle(milestone)}
      >
        {milestone.is_completed ? (
          <CheckCircle2 className="h-5 w-5 text-primary" />
        ) : (
          <Circle className="h-5 w-5 text-muted-foreground" />
        )}
      </Button>
      <div className="flex-1 min-w-0">
        <h6 className="text-sm font-medium leading-none mb-1 capitalize">
          {milestone.milestone_name}
        </h6>
        <div className="text-xs text-muted-foreground flex gap-2 items-center">
          <span className="bg-secondary px-1.5 py-0.5 rounded uppercase text-[10px] tracking-wider">
            {milestone.category}
          </span>
          {milestone.is_completed && milestone.completion_date && (
            <>
              {editingDate ? (
                <Input
                  type="date"
                  className="h-6 w-36 text-xs"
                  defaultValue={format(
                    new Date(milestone.completion_date),
                    "yyyy-MM-dd",
                  )}
                  autoFocus
                  onBlur={(e) => {
                    setEditingDate(false);
                    if (e.target.value) {
                      onDateChange(milestone, e.target.value);
                    }
                  }}
                  onKeyDown={(e) => {
                    if (e.key === "Enter") {
                      setEditingDate(false);
                      if (e.currentTarget.value) {
                        onDateChange(milestone, e.currentTarget.value);
                      }
                    }
                    if (e.key === "Escape") {
                      setEditingDate(false);
                    }
                  }}
                />
              ) : (
                <button
                  type="button"
                  className="hover:underline cursor-pointer"
                  onClick={() => setEditingDate(true)}
                  title="Click to edit date"
                >
                  Completed{" "}
                  {format(new Date(milestone.completion_date), "MMM d, yyyy")}
                </button>
              )}
            </>
          )}
        </div>
        {milestone.notes && (
          <p className="text-xs text-muted-foreground mt-2 italic bg-muted p-2 rounded">
            &ldquo;{milestone.notes}&rdquo;
          </p>
        )}
      </div>
      <div className="opacity-0 group-hover:opacity-100 transition-opacity absolute right-4 flex gap-1">
        <Button
          variant="ghost"
          size="icon"
          className="h-8 w-8 text-muted-foreground hover:text-foreground"
          onClick={() => setEditing(true)}
        >
          <Pencil className="h-3.5 w-3.5" />
        </Button>
        <RecordContextProvider value={milestone}>
          <DeleteButton
            resource="listing_milestones"
            redirect={false}
            size="icon"
            variant="ghost"
            label=""
            className="h-8 w-8 text-muted-foreground hover:bg-destructive/10 hover:text-destructive"
          />
        </RecordContextProvider>
      </div>
    </div>
  );
};
