import { CalendarDays, ExternalLink, KeyRound, MapPin } from "lucide-react";
import { useRecordContext } from "ra-core";
import { EditButton } from "@/components/admin/edit-button";
import { DeleteButton } from "@/components/admin/delete-button";
import { ReferenceField } from "@/components/admin/reference-field";
import { ReferenceArrayField } from "@/components/admin/reference-array-field";
import { ShowButton } from "@/components/admin/show-button";
import { TextField } from "@/components/admin/text-field";
import { DateField } from "@/components/admin/date-field";

import { AsideSection } from "../misc/AsideSection";
import type { ListingView } from "../types";

interface ListingAsideProps {
  link?: string;
}

export const ListingAside = ({ link = "edit" }: ListingAsideProps) => {
  const record = useRecordContext<ListingView>();
  if (!record) return null;

  return (
    <div className="hidden sm:block w-92 min-w-92 space-y-4">
      <div className="flex flex-row space-x-1">
        {link === "edit" ? (
          <EditButton label="Edit Listing" />
        ) : (
          <ShowButton label="Show Listing" />
        )}
      </div>

      <ListingInfo record={record} />

      <AddressInfo record={record} />

      <ContextInfo record={record} />

      <ListingContactsAside record={record} />

      <AdditionalInfo record={record} />

      {link !== "edit" && (
        <div className="mt-6 pt-6 border-t hidden sm:flex flex-col gap-2 items-start">
          <DeleteButton
            className="h-6 cursor-pointer hover:bg-destructive/10! text-destructive! border-destructive! focus-visible:ring-destructive/20 dark:focus-visible:ring-destructive/40"
            size="sm"
          />
        </div>
      )}
    </div>
  );
};

export const ListingInfo = ({ record }: { record: ListingView }) => {
  if (
    !record.showing_instructions &&
    !record.lockbox_serial &&
    !record.listing_expiration &&
    !record.photo_folder_url &&
    !record.disclosures_url
  ) {
    return null;
  }

  return (
    <AsideSection title="Showing & Access">
      {record.lockbox_serial && (
        <div className="flex flex-row items-center gap-2 min-h-[24px]">
          <KeyRound className="w-4 h-4 text-muted-foreground" />
          <span className="text-sm">Lockbox: {record.lockbox_serial}</span>
        </div>
      )}
      {record.showing_instructions && (
        <div className="flex flex-row items-start gap-2 min-h-[24px] mt-1">
          <MapPin className="w-4 h-4 text-muted-foreground shrink-0 mt-0.5" />
          <span className="text-sm">{record.showing_instructions}</span>
        </div>
      )}
      {record.photo_folder_url && (
        <div className="flex flex-row items-center gap-2 min-h-[24px] mt-1">
          <ExternalLink className="w-4 h-4 text-muted-foreground shrink-0" />
          <a
            href={record.photo_folder_url}
            target="_blank"
            rel="noopener noreferrer"
            className="text-sm hover:underline"
          >
            Photo Drive
          </a>
        </div>
      )}
      {record.disclosures_url && (
        <div className="flex flex-row items-center gap-2 min-h-[24px] mt-1">
          <ExternalLink className="w-4 h-4 text-muted-foreground shrink-0" />
          <a
            href={record.disclosures_url}
            target="_blank"
            rel="noopener noreferrer"
            className="text-sm hover:underline"
          >
            Disclosures
          </a>
        </div>
      )}
      {record.listing_expiration && (
        <div className="flex flex-row items-center gap-2 min-h-[24px] mt-1">
          <CalendarDays className="w-4 h-4 text-muted-foreground" />
          <span className="text-sm text-muted-foreground">
            Expires on{" "}
            <DateField
              source="listing_expiration"
              record={record}
              transform={(v: unknown) =>
                typeof v === "string"
                  ? new Date(v.slice(0, 10) + "T00:00:00")
                  : v instanceof Date
                    ? v
                    : undefined
              }
            />
          </span>
        </div>
      )}
    </AsideSection>
  );
};

export const ContextInfo = ({ record }: { record: ListingView }) => {
  if (!record.list_price && !record.id) {
    return null;
  }

  return (
    <AsideSection title="Property Details">
      {record.list_price && (
        <span className="text-sm">
          Price:{" "}
          {new Intl.NumberFormat("en-US", {
            style: "currency",
            currency: "USD",
            maximumFractionDigits: 0,
          }).format(record.list_price)}
        </span>
      )}
    </AsideSection>
  );
};

export const AddressInfo = ({ record }: { record: ListingView }) => {
  if (!record.unparsed_address) {
    return null;
  }

  return (
    <AsideSection title="Main Address" noGap>
      <TextField source="unparsed_address" />
    </AsideSection>
  );
};

export const AdditionalInfo = ({ record: _ }: { record: ListingView }) => {
  return null;
};

import { useListContext } from "ra-core";
import { Link as RouterLink } from "react-router-dom";
import { Avatar } from "../contacts/Avatar";

const ContactArrayRenderer = () => {
  const { data, isPending } = useListContext<any>();
  if (isPending || !data) return null;
  return (
    <div className="flex flex-col gap-1">
      {data.map((contact) => (
        <ContactCard key={contact.id} contact={contact} />
      ))}
    </div>
  );
};

const ContactCard = ({ contact: explicitContact }: { contact?: any } = {}) => {
  const contextContact = useRecordContext<any>();
  const contact = explicitContact || contextContact;
  if (!contact) return null;
  return (
    <div className="flex flex-row gap-4 items-center mb-3">
      <Avatar record={contact} />
      <div className="flex flex-col">
        <RouterLink
          to={`/contacts/${contact.id}/show`}
          className="text-sm hover:underline"
        >
          {contact.first_name} {contact.last_name}
        </RouterLink>
        <span className="text-xs text-muted-foreground">
          {contact.title}
          {contact.title && contact.company_name && " at "}
          {contact.company_name}
        </span>
      </div>
    </div>
  );
};

export const ListingContactsAside = ({ record }: { record: ListingView }) => {
  if (
    !record.seller_id &&
    (!record.contact_ids || record.contact_ids.length === 0)
  ) {
    return null;
  }

  return (
    <AsideSection title="Contacts">
      <div className="flex flex-col gap-2">
        {record.seller_id && (
          <div>
            <span className="text-xs text-muted-foreground uppercase tracking-widest block mb-2">
              Primary Seller
            </span>
            <ReferenceField
              reference="contacts_summary"
              source="seller_id"
              record={record}
            >
              <ContactCard />
            </ReferenceField>
          </div>
        )}

        {record.contact_ids && record.contact_ids.length > 0 && (
          <div className="mt-2">
            <span className="text-xs text-muted-foreground uppercase tracking-widest block mb-1">
              Other Contacts
            </span>
            <ReferenceArrayField
              reference="contacts_summary"
              source="contact_ids"
            >
              <ContactArrayRenderer />
            </ReferenceArrayField>
          </div>
        )}
      </div>
    </AsideSection>
  );
};
