import { useCreate, useNotify } from "ra-core";
import { AutocompleteInput } from "@/components/admin/autocomplete-input";

export const AutocompleteHouseholdInput = () => {
  const [create] = useCreate();
  const notify = useNotify();

  const handleCreateHousehold = async (name?: string) => {
    if (!name) return;
    try {
      const newHousehold = await create(
        "households",
        {
          data: {
            name,
            created_at: new Date().toISOString(),
          },
        },
        { returnPromise: true },
      );
      return newHousehold;
    } catch {
      notify("An error occurred while creating the household", {
        type: "error",
      });
    }
  };

  return (
    <AutocompleteInput
      optionText="name"
      helperText={false}
      onCreate={handleCreateHousehold}
      createItemLabel="Create %{item}"
      createLabel="Start typing to create a new household"
      filterToQuery={(searchText: string) => ({
        "name@ilike": `%${searchText}%`,
      })}
    />
  );
};
