import { RecordContextProvider, useListContext } from "ra-core";
import { Fragment } from "react";

import type { ListingView } from "../types";
import { ListingCard } from "./ListingCard";

const STATUS_GROUP_RANKS: Record<string, number> = {
  active: 0,
  pending: 1,
  closed: 2,
  sold: 2,
  withdrawn: 3,
  prospective: 4,
};

const STATUS_GROUP_LABELS = [
  "Active",
  "Pending",
  "Closed",
  "Withdrawn",
  "Prospective",
];

const times = (nbChildren: number, fn: (key: number) => any) =>
  Array.from({ length: nbChildren }, (_, key) => fn(key));

const parseSelectedStatuses = (value?: string) =>
  value
    ? value
        .replace(/[()]/g, "")
        .split(",")
        .map((status) => status.trim())
        .filter(Boolean)
    : [];

const getStatusRank = (status?: string) => {
  const normalizedStatus = status?.trim().toLowerCase() ?? "";
  return STATUS_GROUP_RANKS[normalizedStatus] ?? Number.MAX_SAFE_INTEGER;
};

const groupListingsByStatus = (records: ListingView[]) =>
  [...records].sort(
    (left, right) =>
      getStatusRank(left.standard_status) -
      getStatusRank(right.standard_status),
  );

const buildStatusGroups = (records: ListingView[]) => {
  const groups = new Map<number, ListingView[]>();

  records.forEach((record) => {
    const rank = getStatusRank(record.standard_status);
    if (!groups.has(rank)) {
      groups.set(rank, []);
    }
    groups.get(rank)?.push(record);
  });

  return [...groups.entries()]
    .sort(([leftRank], [rightRank]) => leftRank - rightRank)
    .map(([rank, groupRecords]) => ({
      label: STATUS_GROUP_LABELS[rank] ?? "Other",
      records: groupRecords,
    }));
};

const LoadingGridList = () => (
  <div className="flex flex-wrap w-[1008px] gap-1">
    {times(15, (key) => (
      <div
        className="h-[200px] w-[194px] flex flex-col bg-gray-200"
        key={key}
      />
    ))}
  </div>
);

const LoadedGridList = () => {
  const { data, error, isPending, filterValues } =
    useListContext<ListingView>();

  if (isPending || error) return null;

  const selectedStatuses = parseSelectedStatuses(
    filterValues?.["standard_status@in"],
  );
  const shouldGroupByStatus = selectedStatuses.length > 1;
  const records = shouldGroupByStatus ? groupListingsByStatus(data) : data;
  const groupedRecords = shouldGroupByStatus ? buildStatusGroups(records) : [];

  return (
    <div
      className="w-full gap-2 grid"
      style={{
        gridTemplateColumns: "repeat(auto-fill, minmax(180px, 1fr))",
      }}
    >
      {shouldGroupByStatus
        ? groupedRecords.map((group) => (
            <Fragment key={group.label}>
              <div
                className="col-span-full mt-2 first:mt-0 px-1 text-xs font-semibold uppercase tracking-[0.24em] text-muted-foreground/90"
                style={{ gridColumn: "1 / -1" }}
              >
                {group.label}
              </div>
              {group.records.map((record) => (
                <RecordContextProvider key={record.id} value={record}>
                  <ListingCard />
                </RecordContextProvider>
              ))}
            </Fragment>
          ))
        : records.map((record) => (
            <RecordContextProvider key={record.id} value={record}>
              <ListingCard />
            </RecordContextProvider>
          ))}

      {records.length === 0 && <div className="p-2">No listings found</div>}
    </div>
  );
};

export const ImageList = () => {
  const { isPending } = useListContext();
  return isPending ? <LoadingGridList /> : <LoadedGridList />;
};
