import { useGetList, useRecordContext } from "ra-core";
import { Link } from "react-router-dom";
import { Home, Users } from "lucide-react";

import type { Contact } from "../types";

export const HouseholdMembers = () => {
  const record = useRecordContext<Contact>();

  if (!record?.household_id) {
    return (
      <p className="text-sm text-muted-foreground italic">
        No household assigned
      </p>
    );
  }

  return <HouseholdMembersList record={record} />;
};

const HouseholdMembersList = ({ record }: { record: Contact }) => {
  const { data, isPending } = useGetList<Contact>("contacts", {
    filter: { household_id: record.household_id },
    sort: { field: "last_name", order: "ASC" },
    pagination: { page: 1, perPage: 20 },
  });

  if (isPending) {
    return <p className="text-sm text-muted-foreground">Loading members...</p>;
  }

  const otherMembers = data?.filter((c) => c.id !== record.id) ?? [];

  if (otherMembers.length === 0) {
    return (
      <div className="flex flex-col gap-1">
        {record.household_name && (
          <div className="flex items-center gap-2">
            <Home className="w-4 h-4 text-muted-foreground" />
            <span className="text-sm font-medium">{record.household_name}</span>
          </div>
        )}
        <p className="pl-6 text-sm text-muted-foreground italic">
          No other members
        </p>
      </div>
    );
  }

  return (
    <div className="flex flex-col gap-1">
      {record.household_name && (
        <div className="flex items-center gap-2 mb-1">
          <Home className="w-4 h-4 text-muted-foreground" />
          <span className="text-sm font-medium">{record.household_name}</span>
        </div>
      )}
      {otherMembers.map((member) => (
        <div key={member.id} className="flex items-center gap-2 pl-6">
          <Users className="w-3.5 h-3.5 text-muted-foreground" />
          <Link
            to={`/contacts/${member.id}/show`}
            className="text-sm underline hover:no-underline text-primary"
          >
            {member.first_name} {member.last_name}
          </Link>
        </div>
      ))}
    </div>
  );
};
