import { supabaseDataProvider } from "ra-supabase-core";
import {
  withLifecycleCallbacks,
  type CreateParams,
  type DataProvider,
  type DeleteManyParams,
  type DeleteParams,
  type GetListParams,
  type Identifier,
  type ResourceCallbacks,
  type UpdateParams,
} from "ra-core";
import type {
  Contact,
  ContactNote,
  Deal,
  DealNote,
  ListingNote,
  RAFile,
  Sale,
  SalesFormData,
  SignUpData,
} from "../../types";
import type { ConfigurationContextValue } from "../../root/ConfigurationContext";
import { getActivityLog } from "../commons/activity";
import { getContactAvatar } from "../commons/getContactAvatar";
import {
  ATTACHMENTS_BUCKET,
  PUBLIC_ASSETS_BUCKET,
} from "../commons/attachments";
import { getIsInitialized } from "./authProvider";
import { supabase } from "./supabase";

if (import.meta.env.VITE_SUPABASE_URL === undefined) {
  throw new Error("Please set the VITE_SUPABASE_URL environment variable");
}
if (import.meta.env.VITE_SB_PUBLISHABLE_KEY === undefined) {
  throw new Error(
    "Please set the VITE_SB_PUBLISHABLE_KEY environment variable",
  );
}

const baseDataProvider = supabaseDataProvider({
  instanceUrl: import.meta.env.VITE_SUPABASE_URL,
  apiKey: import.meta.env.VITE_SB_PUBLISHABLE_KEY,
  supabaseClient: supabase,
  sortOrder: "asc,desc.nullslast" as any,
});

const processCompanyLogo = async (params: any) => {
  const logo = params.data.logo;

  if (logo?.rawFile instanceof File) {
    await uploadToBucket(logo, PUBLIC_ASSETS_BUCKET);
  }

  return {
    ...params,
    data: {
      ...params.data,
      logo,
    },
  };
};

async function processContactAvatar(
  params: UpdateParams<Contact>,
): Promise<UpdateParams<Contact>>;

async function processContactAvatar(
  params: CreateParams<Contact>,
): Promise<CreateParams<Contact>>;

async function processContactAvatar(
  params: CreateParams<Contact> | UpdateParams<Contact>,
): Promise<CreateParams<Contact> | UpdateParams<Contact>> {
  const { data } = params;
  if (data.avatar?.src || !data.email_jsonb || !data.email_jsonb.length) {
    return params;
  }
  const avatarUrl = await getContactAvatar(data);

  // Clone the data and modify the clone
  const newData = { ...data, avatar: { src: avatarUrl || undefined } };

  return { ...params, data: newData };
}

const mapListingViewToRecord = (record: any) => ({
  ...record,
  id: record.listing_key,
  thumbnail: record.thumbnail_url
    ? { src: record.thumbnail_url, title: "Cover image" }
    : null,
});

const dataProviderWithCustomMethods = {
  ...baseDataProvider,
  async getList(resource: string, params: GetListParams) {
    if (resource === "companies") {
      return baseDataProvider.getList("companies_summary", params);
    }
    if (resource === "contacts") {
      return baseDataProvider.getList("contacts_summary", params);
    }
    if (resource === "listings") {
      const mappedParams = { ...params };
      if (mappedParams.sort && mappedParams.sort.field === "id") {
        mappedParams.sort = { ...mappedParams.sort, field: "listing_key" };
      }

      const response = await baseDataProvider.getList(
        "listings_view",
        mappedParams,
      );
      return {
        ...response,
        data: response.data.map(mapListingViewToRecord),
      };
    }

    return baseDataProvider.getList(resource, params);
  },
  async getOne(resource: string, params: any) {
    if (resource === "companies") {
      return baseDataProvider.getOne("companies_summary", params);
    }
    if (resource === "contacts") {
      return baseDataProvider.getOne("contacts_summary", params);
    }
    if (resource === "listings") {
      const { data, error } = await supabase
        .from("listings_view")
        .select("*")
        .eq("listing_key", params.id)
        .single();

      if (error) {
        console.error("Listing getOne error", error);
        throw error;
      }
      return { data: mapListingViewToRecord(data) };
    }

    return baseDataProvider.getOne(resource, params);
  },
  async getMany(resource: string, params: { ids: Identifier[] }) {
    if (resource === "listings") {
      const { data, error } = await supabase
        .from("listings_view")
        .select("*")
        .in("listing_key", params.ids);

      if (error) {
        console.error("Listing getMany error", error);
        throw error;
      }
      return { data: data.map(mapListingViewToRecord) } as any;
    }
    return baseDataProvider.getMany(resource, params);
  },
  async create(resource: string, params: CreateParams) {
    if (resource === "listings") {
      const {
        unparsed_address,
        city,
        list_price,
        sales_id,
        initial_note,
        thumbnail,
      } = params.data;

      if (!unparsed_address) {
        throw new Error("Address is required to create a listing");
      }

      const listing_key = `PROSP-${crypto.randomUUID()}`;

      let thumbnail_url: string | null = null;
      if (thumbnail?.rawFile) {
        const uploaded = await uploadToBucket(thumbnail, PUBLIC_ASSETS_BUCKET);
        thumbnail_url = uploaded.src ?? null;
      }

      const { error: insertError } = await supabase
        .from("prospective_listings")
        .insert({
          listing_key,
          unparsed_address,
          city: city || null,
          list_price: list_price ?? null,
          sales_id: sales_id || null,
          standard_status: "Prospective",
          thumbnail_url,
        });

      if (insertError) {
        console.error("Prospective listing create error", insertError);
        throw insertError;
      }

      if (initial_note && sales_id) {
        const { error: noteError } = await supabase
          .from("listing_notes")
          .insert({
            listing_id: listing_key,
            text: initial_note,
            sales_id,
          });
        if (noteError) {
          console.error("Initial listing note create error", noteError);
        }
      }

      return {
        data: {
          ...params.data,
          listing_key,
          id: listing_key,
          standard_status: "Prospective",
        },
      } as any;
    }
    return baseDataProvider.create(resource, params);
  },
  async update(resource: string, params: UpdateParams) {
    if (resource === "listings") {
      const { id, data, previousData } = params;
      const {
        listing_expiration,
        lockbox_serial,
        flyer_file_path,
        photo_folder_url,
        disclosures_url,
        showing_instructions,
        seller_id,
        contact_ids,
        thumbnail,
      } = data;

      const { error } = await supabase.from("listing_supplements").upsert(
        {
          listing_key: id as string,
          listing_expiration: listing_expiration || null,
          lockbox_serial: lockbox_serial || null,
          flyer_file_path: flyer_file_path || null,
          photo_folder_url: photo_folder_url || null,
          disclosures_url: disclosures_url || null,
          showing_instructions: showing_instructions || null,
          seller_id: seller_id || null,
          contact_ids: contact_ids || null,
        },
        {
          onConflict: "listing_key",
        },
      );

      if (error) {
        console.error("Listing update error", error);
        throw error;
      }

      const isProspective = String(id).startsWith("PROSP-");
      if (isProspective) {
        let thumbnail_url: string | null = null;
        if (thumbnail?.rawFile) {
          const uploaded = await uploadToBucket(
            thumbnail,
            PUBLIC_ASSETS_BUCKET,
          );
          thumbnail_url = uploaded.src ?? null;
        } else if (thumbnail?.src) {
          thumbnail_url = thumbnail.src;
        }

        const prospUpdate: Record<string, unknown> = { thumbnail_url };
        if (typeof data.standard_status === "string") {
          prospUpdate.standard_status = data.standard_status;
        }

        const { error: prospError } = await supabase
          .from("prospective_listings")
          .update(prospUpdate)
          .eq("listing_key", id as string);

        if (prospError) {
          console.error("Prospective listing update error", prospError);
          throw prospError;
        }
      }

      return { data: { ...previousData, ...data } } as any;
    }
    return baseDataProvider.update(resource, params);
  },
  async delete(resource: string, params: DeleteParams) {
    if (resource === "listings") {
      const id = params.id as string;
      const isProspective = String(id).startsWith("PROSP-");
      if (!isProspective) {
        throw new Error(
          "Only prospective listings can be deleted; MLS-backed listings are read-only.",
        );
      }

      await supabase.from("listing_supplements").delete().eq("listing_key", id);
      await supabase.from("listing_notes").delete().eq("listing_id", id);
      await supabase.from("listing_milestones").delete().eq("listing_key", id);
      await supabase.from("listing_inquiries").delete().eq("listing_key", id);

      const { error } = await supabase
        .from("prospective_listings")
        .delete()
        .eq("listing_key", id);

      if (error) {
        console.error("Prospective listing delete error", error);
        throw error;
      }

      return { data: (params.previousData ?? { id }) as any };
    }
    return baseDataProvider.delete(resource, params);
  },
  async deleteMany(resource: string, params: DeleteManyParams) {
    if (resource === "listings") {
      const ids = params.ids.map(String);
      const prospectiveIds = ids.filter((id) => id.startsWith("PROSP-"));
      if (prospectiveIds.length !== ids.length) {
        throw new Error(
          "Only prospective listings can be deleted; MLS-backed listings are read-only.",
        );
      }

      await supabase
        .from("listing_supplements")
        .delete()
        .in("listing_key", prospectiveIds);
      await supabase
        .from("listing_notes")
        .delete()
        .in("listing_id", prospectiveIds);
      await supabase
        .from("listing_milestones")
        .delete()
        .in("listing_key", prospectiveIds);
      await supabase
        .from("listing_inquiries")
        .delete()
        .in("listing_key", prospectiveIds);

      const { error } = await supabase
        .from("prospective_listings")
        .delete()
        .in("listing_key", prospectiveIds);

      if (error) {
        console.error("Prospective listings deleteMany error", error);
        throw error;
      }

      return { data: prospectiveIds as any };
    }
    return baseDataProvider.deleteMany(resource, params);
  },

  async signUp({ email, password, first_name, last_name }: SignUpData) {
    const response = await supabase.auth.signUp({
      email,
      password,
      options: {
        data: {
          first_name,
          last_name,
        },
      },
    });

    if (!response.data?.user || response.error) {
      console.error("signUp.error", response.error);
      throw new Error(response?.error?.message || "Failed to create account");
    }

    // Update the is initialized cache in localStorage
    window.localStorage.setItem("RaStore.auth.is_initialized", "true");

    return {
      id: response.data.user.id,
      email,
      password,
    };
  },
  async salesCreate(body: SalesFormData) {
    const { data, error } = await supabase.functions.invoke<{ data: Sale }>(
      "users",
      {
        method: "POST",
        body,
      },
    );

    if (!data || error) {
      console.error("salesCreate.error", error);
      const errorDetails = await (async () => {
        try {
          return (await error?.context?.json()) ?? {};
        } catch {
          return {};
        }
      })();
      throw new Error(errorDetails?.message || "Failed to create the user");
    }

    return data.data;
  },
  async salesUpdate(
    id: Identifier,
    data: Partial<Omit<SalesFormData, "password">>,
  ) {
    const { email, first_name, last_name, administrator, avatar, disabled } =
      data;

    const { data: updatedData, error } = await supabase.functions.invoke<{
      data: Sale;
    }>("users", {
      method: "PATCH",
      body: {
        sales_id: id,
        email,
        first_name,
        last_name,
        administrator,
        disabled,
        avatar,
      },
    });

    if (!updatedData || error) {
      console.error("salesCreate.error", error);
      throw new Error("Failed to update account manager");
    }

    return updatedData.data;
  },
  async updatePassword(id: Identifier) {
    const { data: passwordUpdated, error } =
      await supabase.functions.invoke<boolean>("update_password", {
        method: "PATCH",
        body: {
          sales_id: id,
        },
      });

    if (!passwordUpdated || error) {
      console.error("update_password.error", error);
      throw new Error("Failed to update password");
    }

    return passwordUpdated;
  },
  async unarchiveDeal(deal: Deal) {
    // get all deals where stage is the same as the deal to unarchive
    const { data: deals } = await baseDataProvider.getList<Deal>("deals", {
      filter: { stage: deal.stage },
      pagination: { page: 1, perPage: 1000 },
      sort: { field: "index", order: "ASC" },
    });

    // set index for each deal starting from 1, if the deal to unarchive is found, set its index to the last one
    const updatedDeals = deals.map((d, index) => ({
      ...d,
      index: d.id === deal.id ? 0 : index + 1,
      archived_at: d.id === deal.id ? null : d.archived_at,
    }));

    return await Promise.all(
      updatedDeals.map((updatedDeal) =>
        baseDataProvider.update("deals", {
          id: updatedDeal.id,
          data: updatedDeal,
          previousData: deals.find((d) => d.id === updatedDeal.id),
        }),
      ),
    );
  },
  async getActivityLog(companyId?: Identifier) {
    return getActivityLog(baseDataProvider, companyId);
  },
  async isInitialized() {
    return getIsInitialized();
  },
  async convertProspectiveListing(oldKey: string, newKey: string) {
    const { error } = await supabase.rpc("convert_prospective_listing", {
      p_old_key: oldKey,
      p_new_key: newKey,
    });
    if (error) {
      console.error("convertProspectiveListing.error", error);
      throw new Error(error.message || "Failed to convert listing");
    }
    return { newKey };
  },
  async mergeContacts(sourceId: Identifier, targetId: Identifier) {
    const { data, error } = await supabase.functions.invoke("merge_contacts", {
      method: "POST",
      body: { loserId: sourceId, winnerId: targetId },
    });

    if (error) {
      console.error("merge_contacts.error", error);
      throw new Error("Failed to merge contacts");
    }

    return data;
  },
  async getConfiguration(): Promise<ConfigurationContextValue> {
    const { data } = await baseDataProvider.getOne("configuration", { id: 1 });
    return (data?.config as ConfigurationContextValue) ?? {};
  },
  async updateConfiguration(
    config: ConfigurationContextValue,
  ): Promise<ConfigurationContextValue> {
    const { data } = await baseDataProvider.update("configuration", {
      id: 1,
      data: { config },
      previousData: { id: 1 },
    });
    return data.config as ConfigurationContextValue;
  },
} satisfies DataProvider;

export type CrmDataProvider = typeof dataProviderWithCustomMethods;

const processConfigLogo = async (logo: any): Promise<string> => {
  if (typeof logo === "string") return logo;
  if (logo?.rawFile instanceof File) {
    await uploadToBucket(logo, PUBLIC_ASSETS_BUCKET);
    return logo.src;
  }
  return logo?.src ?? "";
};

const lifeCycleCallbacks: ResourceCallbacks[] = [
  {
    resource: "configuration",
    beforeUpdate: async (params) => {
      const config = params.data.config;
      if (config) {
        config.lightModeLogo = await processConfigLogo(config.lightModeLogo);
        config.darkModeLogo = await processConfigLogo(config.darkModeLogo);
      }
      return params;
    },
  },
  {
    resource: "contact_notes",
    beforeSave: async (data: ContactNote, _, __) => {
      if (data.attachments) {
        data.attachments = await Promise.all(
          data.attachments.map((fi) => uploadToBucket(fi)),
        );
      }
      return data;
    },
  },
  {
    resource: "deal_notes",
    beforeSave: async (data: DealNote, _, __) => {
      if (data.attachments) {
        data.attachments = await Promise.all(
          data.attachments.map((fi) => uploadToBucket(fi)),
        );
      }
      return data;
    },
  },
  {
    resource: "listing_notes",
    beforeSave: async (data: ListingNote, _, __) => {
      if (data.attachments) {
        data.attachments = await Promise.all(
          data.attachments.map((fi) => uploadToBucket(fi)),
        );
      }
      return data;
    },
  },
  {
    resource: "sales",
    beforeSave: async (data: Sale, _, __) => {
      if (data.avatar) {
        await uploadToBucket(data.avatar, PUBLIC_ASSETS_BUCKET);
      }
      return data;
    },
  },
  {
    resource: "contacts",
    beforeCreate: async (params) => {
      return processContactAvatar(params);
    },
    beforeUpdate: async (params) => {
      return processContactAvatar(params);
    },
    beforeGetList: async (params) => {
      return applyFullTextSearch([
        "first_name",
        "last_name",
        "company_name",
        "title",
        "email",
        "phone",
        "background",
      ])(params);
    },
  },
  {
    resource: "companies",
    beforeGetList: async (params) => {
      return applyFullTextSearch([
        "name",
        "phone_number",
        "website",
        "zipcode",
        "city",
        "state_abbr",
      ])(params);
    },
    beforeCreate: async (params) => {
      const createParams = await processCompanyLogo(params);

      return {
        ...createParams,
        data: {
          created_at: new Date().toISOString(),
          ...createParams.data,
        },
      };
    },
    beforeUpdate: async (params) => {
      return await processCompanyLogo(params);
    },
  },
  {
    resource: "contacts_summary",
    beforeGetList: async (params) => {
      return applyFullTextSearch(["first_name", "last_name"])(params);
    },
  },
  {
    resource: "listings",
    beforeGetList: async (params) => {
      return applyFullTextSearch(["unparsed_address", "city", "listing_id"])(
        params,
      );
    },
  },
  {
    resource: "deals",
    beforeGetList: async (params) => {
      return applyFullTextSearch(["name", "category", "description"])(params);
    },
  },
  {
    resource: "contact_connections",
    beforeGetList: async (params) => {
      // Transform contact_id filter into bidirectional OR filter for PostgREST
      // contact_id should match either contact_id_a OR contact_id_b
      const contactId = params.filter?.contact_id;

      if (contactId != null) {
        const { contact_id: _, ...restFilter } = params.filter;
        return {
          ...params,
          filter: {
            ...restFilter,
            "@or": {
              "contact_id_a@eq": contactId,
              "contact_id_b@eq": contactId,
            },
          },
        };
      }

      return params;
    },
  },
];

export const dataProvider = withLifecycleCallbacks(
  dataProviderWithCustomMethods,
  lifeCycleCallbacks,
) as CrmDataProvider;

const applyFullTextSearch = (columns: string[]) => (params: GetListParams) => {
  if (!params.filter?.q) {
    return params;
  }
  const { q, ...filter } = params.filter;
  return {
    ...params,
    filter: {
      ...filter,
      "@or": columns.reduce((acc, column) => {
        if (column === "email")
          return {
            ...acc,
            [`email_fts@ilike`]: q,
          };
        if (column === "phone")
          return {
            ...acc,
            [`phone_fts@ilike`]: q,
          };
        else
          return {
            ...acc,
            [`${column}@ilike`]: q,
          };
      }, {}),
    },
  };
};

const uploadToBucket = async (
  fi: RAFile,
  bucket: string = ATTACHMENTS_BUCKET,
) => {
  if (!fi.src.startsWith("blob:") && !fi.src.startsWith("data:")) {
    // Sign URL check if path exists in the bucket
    if (fi.path) {
      const { error } = await supabase.storage
        .from(bucket)
        .createSignedUrl(fi.path, 60);

      if (!error) {
        return fi;
      }
    }
  }

  const dataContent = fi.src
    ? await fetch(fi.src)
        .then((res) => {
          if (res.status !== 200) {
            return null;
          }
          return res.blob();
        })
        .catch(() => null)
    : fi.rawFile;

  if (dataContent == null) {
    // We weren't able to download the file from its src (e.g. user must be signed in on another website to access it)
    // or the file has no content (not probable)
    // In that case, just return it as is: when trying to download it, users should be redirected to the other website
    // and see they need to be signed in. It will then be their responsibility to upload the file back to the note.
    return fi;
  }

  const file = fi.rawFile;
  const fileParts = file.name.split(".");
  const fileExt = fileParts.length > 1 ? `.${file.name.split(".").pop()}` : "";
  const fileName = `${crypto.randomUUID()}${fileExt}`;
  const filePath = `${fileName}`;
  const { error: uploadError } = await supabase.storage
    .from(bucket)
    .upload(filePath, dataContent);

  if (uploadError) {
    console.error("uploadError", uploadError);
    throw new Error("Failed to upload attachment");
  }

  const { data } = supabase.storage.from(bucket).getPublicUrl(filePath);

  fi.path = filePath;
  fi.src = data.publicUrl;

  // save MIME type
  const mimeType = file.type;
  fi.type = mimeType;

  return fi;
};
