import { useGetIdentity, useListContext } from "ra-core";
import { useIsMobile } from "@/hooks/use-mobile";
import MobileHeader from "../layout/MobileHeader";
import { MobileContent } from "../layout/MobileContent";
import { CreateButton } from "@/components/admin/create-button";
import { ExportButton } from "@/components/admin/export-button";
import { List } from "@/components/admin/list";
import { ListPagination } from "@/components/admin/list-pagination";
import { SortButton } from "@/components/admin/sort-button";

import { TopToolbar } from "../layout/TopToolbar";
import { ListingEmpty } from "./ListingEmpty";
import { ListingListFilter } from "./ListingListFilter";
import { ImageList } from "./GridList";

export const ListingList = () => {
  const { identity } = useGetIdentity();
  const isMobile = useIsMobile();
  if (!identity) return null;
  return (
    <List
      title={false}
      perPage={25}
      sort={{ field: "list_price", order: "ASC" }}
      filterDefaultValues={{ "standard_status@in": "(Active,Pending)" }}
      actions={isMobile ? <div className="hidden" /> : <ListingListActions />}
      pagination={<ListPagination rowsPerPageOptions={[10, 25, 50, 100]} />}
      queryOptions={{ refetchInterval: 60 * 1000 }}
    >
      <ListingListLayout />
    </List>
  );
};

const ListingListLayout = () => {
  const { data, isPending, filterValues } = useListContext();
  const isMobile = useIsMobile();
  const hasFilters = filterValues && Object.keys(filterValues).length > 0;

  if (isPending) return null;
  if (!data?.length && !hasFilters)
    return (
      <div className="w-full">
        {isMobile && (
          <MobileHeader>
            <ListingListFilter />
          </MobileHeader>
        )}
        {isMobile ? (
          <MobileContent>
            <ListingEmpty />
          </MobileContent>
        ) : (
          <ListingEmpty />
        )}
      </div>
    );

  return (
    <div className="w-full">
      {isMobile && (
        <MobileHeader>
          <ListingListFilter />
        </MobileHeader>
      )}
      {isMobile ? (
        <MobileContent>
          <div className="flex flex-col flex-1 gap-4">
            <ImageList />
          </div>
        </MobileContent>
      ) : (
        <div className="w-full flex flex-row gap-8">
          <ListingListFilter />
          <div className="flex flex-col flex-1 gap-4">
            <ImageList />
          </div>
        </div>
      )}
    </div>
  );
};

const ListingListActions = () => {
  return (
    <TopToolbar>
      <SortButton
        fields={["unparsed_address", "list_price", "days_on_market"]}
      />
      <ExportButton />
      <CreateButton label="New Listing" />
    </TopToolbar>
  );
};
