import { memo } from "react";
import { useRecordContext } from "ra-core";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";

import type { ListingView } from "../types";

const getStatusColor = (status?: string) => {
  switch (status?.toLowerCase()) {
    case "active":
      return "bg-green-100 text-green-700 dark:bg-green-900 dark:text-green-300";
    case "pending":
      return "bg-yellow-100 text-yellow-700 dark:bg-yellow-900 dark:text-yellow-300";
    case "sold":
      return "bg-gray-100 text-gray-700 dark:bg-gray-800 dark:text-gray-300";
    case "prospective":
    default:
      return "bg-blue-100 text-blue-700 dark:bg-blue-900 dark:text-blue-300";
  }
};

// Memoized inner component to prevent re-renders when avatar src hasn't changed
const ListingAvatarInner = memo(
  ({
    src,
    name,
    status,
    sizeClass,
    fallbackClass,
  }: {
    src?: string;
    name: string;
    status?: string;
    sizeClass: string;
    fallbackClass: string;
  }) => (
    <Avatar className={sizeClass}>
      <AvatarImage src={src} alt={name} className="object-contain" />
      <AvatarFallback className={`${fallbackClass} ${getStatusColor(status)}`}>
        🏠
      </AvatarFallback>
    </Avatar>
  ),
  (prev, next) =>
    prev.src === next.src &&
    prev.name === next.name &&
    prev.status === next.status,
);

ListingAvatarInner.displayName = "ListingAvatarInner";

export const ListingAvatar = (props: {
  record?: ListingView;
  width?: 20 | 40;
  height?: 20 | 40;
}) => {
  const { width = 40 } = props;
  const record = useRecordContext<ListingView>(props);
  if (!record) return null;

  const sizeClass = width !== 40 ? `w-[20px] h-[20px]` : "w-10 h-10";
  const fallbackClass = width !== 40 ? "text-xs" : "text-sm";

  return (
    <ListingAvatarInner
      src={undefined}
      name={record.unparsed_address}
      status={record.standard_status}
      sizeClass={sizeClass}
      fallbackClass={fallbackClass}
    />
  );
};
