import { datatype, lorem } from "faker/locale/en_US";
import { randomDate } from "./utils";
import type { Db } from "./types";
import type { ListingMilestone } from "../../../types";

const defaultMilestones = [
  { category: "Pre-listing", name: "Signed listing agreement" },
  { category: "Pre-listing", name: "Confirm pets / alarms / gate codes" },
  { category: "Launch preparation", name: "Photography delivered" },
  { category: "Launch preparation", name: "MLS draft prepared" },
  { category: "Launch", name: "Listing entered into MLS" },
  { category: "Active listing management", name: "Hold weekend open house" },
  { category: "Offer / Negotiation", name: "Confirm offer received" },
  { category: "Closing", name: "Mark sold in MLS" },
];

export const generateListingMilestones = (db: Db): ListingMilestone[] => {
  const milestones: ListingMilestone[] = [];
  let id = 0;

  db.listings.forEach((listing) => {
    // Generate a few milestones for each listing
    defaultMilestones.forEach((m) => {
      const isCompleted = datatype.boolean();
      milestones.push({
        id: id++,
        listing_key: listing.id,
        milestone_name: m.name,
        category: m.category,
        is_completed: isCompleted,
        completion_date: isCompleted ? randomDate().toISOString() : undefined,
        document_file_path: "",
        notes: isCompleted && datatype.boolean() ? lorem.sentence() : "",
      });
    });
  });

  return milestones;
};
