import {
  datatype,
  internet,
  lorem,
  name,
  phone,
  random,
} from "faker/locale/en_US";
import { randomDate } from "./utils";
import type { Db } from "./types";
import type { ListingInquiry } from "../../../types";

export const generateListingInquiries = (
  db: Db,
  size = 150,
): ListingInquiry[] => {
  return Array.from(Array(size).keys()).map((id) => {
    const isFeedback = datatype.boolean();
    return {
      id,
      listing_id: random.arrayElement(db.listings).id, // Note: db.listings must be initialized before this
      type: isFeedback ? "Feedback" : "Inquiry",
      contact_id: datatype.boolean()
        ? random.arrayElement(db.contacts).id
        : undefined,
      date: randomDate().toISOString(),
      name: name.findName(),
      phone: phone.phoneNumber(),
      email: internet.email(),
      rating: isFeedback ? datatype.number({ min: 1, max: 5 }) : undefined,
      comments: lorem.paragraph(),
      sales_id: random.arrayElement(db.sales).id,
    };
  });
};
