import { MapPin, Users } from "lucide-react";
import { useGetIdentity } from "ra-core";
import { ToggleFilterButton } from "@/components/admin/toggle-filter-button";

import { useIsMobile } from "@/hooks/use-mobile";
import { ResponsiveFilters } from "../misc/ResponsiveFilters";
import { FilterCategory } from "../filters/FilterCategory";

const listingStatuses = [
  { id: "Active", name: "Active" },
  { id: "Pending", name: "Pending" },
  { id: "Closed", name: "Closed" },
  { id: "Withdrawn", name: "Withdrawn" },
  { id: "Prospective", name: "Prospective" },
];

export const ListingListFilter = () => {
  const { identity } = useGetIdentity();
  const isMobile = useIsMobile();
  return (
    <ResponsiveFilters searchInput={{ placeholder: "Search listings..." }}>
      <FilterCategory icon={<MapPin className="h-4 w-4" />} label="Status">
        {listingStatuses.map((status) => (
          <ToggleStatusButton
            key={status.id}
            status={status.id}
            label={status.name}
            size={isMobile ? "lg" : undefined}
          />
        ))}
      </FilterCategory>

      <FilterCategory
        icon={<Users className="h-4 w-4" />}
        label="Account Manager"
      >
        <ToggleFilterButton
          className="w-full justify-between h-10 md:h-8"
          label={"Me"}
          value={{ sales_id: identity?.id }}
          size={isMobile ? "lg" : undefined}
        />
      </FilterCategory>
    </ResponsiveFilters>
  );
};

import { Button } from "@/components/ui/button";
import { useListContext } from "ra-core";
import { CircleX } from "lucide-react";
import { cn } from "@/lib/utils";

const ToggleStatusButton = ({
  status,
  label,
  size = "sm",
}: {
  status: string;
  label: string;
  size?: "default" | "sm" | "lg" | "icon" | null | undefined;
}) => {
  const { filterValues, setFilters } = useListContext();

  // PostgREST "in" array format is "(val1,val2)"
  const currentFilter = filterValues["standard_status@in"] || "";
  const statuses = currentFilter
    ? currentFilter.replace(/[()]/g, "").split(",").filter(Boolean)
    : [];

  const isSelected = statuses.includes(status);

  const handleClick = () => {
    let newStatuses;
    if (isSelected) {
      newStatuses = statuses.filter((s: string) => s !== status);
    } else {
      newStatuses = [...statuses, status];
    }

    // Remove the filter completely if array is empty, otherwise format as "(A,B)"
    const newFilterStr = newStatuses.length
      ? `(${newStatuses.join(",")})`
      : undefined;

    setFilters(
      { ...filterValues, "standard_status@in": newFilterStr },
      undefined, // displayedFilters
      false, // no debounce
    );
  };

  return (
    <Button
      variant={isSelected ? "secondary" : "ghost"}
      onClick={handleClick}
      className={cn(
        "cursor-pointer",
        "flex flex-row items-center justify-between gap-2 px-2.5 w-auto md:w-full h-10 md:h-8",
      )}
      size={size}
    >
      {label}
      {isSelected && <CircleX className="opacity-50 w-4 h-4 ml-2" />}
    </Button>
  );
};
