import { memo } from "react";
import {
  AvatarFallback,
  AvatarImage,
  Avatar as ShadcnAvatar,
} from "@/components/ui/avatar";
import { useRecordContext } from "ra-core";

import type { Contact } from "../types";

const getSafeAvatarSrc = (src?: string | null) => {
  if (!src) return undefined;
  if (src === "ERROR") return undefined;
  if (/^https?:\/\//i.test(src) || src.startsWith("data:")) {
    return src;
  }
  return undefined;
};

// Memoized inner component to prevent re-renders when avatar src hasn't changed
const ContactAvatarInner = memo(
  ({
    src,
    firstName,
    lastName,
    sizeClass,
    fallbackClass,
    title,
  }: {
    src?: string;
    firstName?: string;
    lastName?: string;
    sizeClass: string;
    fallbackClass: string;
    title?: string;
  }) => (
    <ShadcnAvatar className={sizeClass} title={title}>
      <AvatarImage src={src} />
      <AvatarFallback className={fallbackClass}>
        {firstName?.charAt(0).toUpperCase()}
        {lastName?.charAt(0).toUpperCase()}
      </AvatarFallback>
    </ShadcnAvatar>
  ),
  (prev, next) =>
    prev.src === next.src &&
    prev.firstName === next.firstName &&
    prev.lastName === next.lastName,
);

ContactAvatarInner.displayName = "ContactAvatarInner";

export const Avatar = (props: {
  record?: Contact;
  width?: 20 | 25 | 40;
  height?: 20 | 25 | 40;
  title?: string;
}) => {
  const record = useRecordContext<Contact>(props);
  const avatarSrc = getSafeAvatarSrc(record?.avatar?.src);
  // If we come from company page, the record is defined (to pass the company as a prop),
  // but neither of those fields are and this lead to an error when creating contact.
  if (!avatarSrc && !record?.first_name && !record?.last_name) {
    return null;
  }

  const size = props.width || props.height;
  const sizeClass =
    props.width === 20
      ? `w-[20px] h-[20px]`
      : props.width === 25
        ? "w-[25px] h-[25px]"
        : "w-10 h-10";
  const fallbackClass = size && size < 40 ? "text-[10px]" : "text-sm";

  return (
    <ContactAvatarInner
      src={avatarSrc}
      firstName={record.first_name}
      lastName={record.last_name}
      sizeClass={sizeClass}
      fallbackClass={fallbackClass}
      title={props.title}
    />
  );
};
