import { DollarSign } from "lucide-react";
import { Link } from "react-router";
import { useCreatePath, useListContext, useRecordContext } from "ra-core";
import { ReferenceManyField } from "@/components/admin/reference-many-field";
import { Card } from "@/components/ui/card";
import { cn } from "@/lib/utils";

import { Avatar as ContactAvatar } from "../contacts/Avatar";
import type { ListingView } from "../types";

const formatExpiration = (value?: string) => {
  if (!value) return null;

  // Slice to date-only (YYYY-MM-DD) to avoid UTC→PST off-by-one
  const date = new Date(value.slice(0, 10) + "T00:00:00");
  if (Number.isNaN(date.getTime())) return null;

  return new Intl.DateTimeFormat("en-US", {
    month: "2-digit",
    day: "2-digit",
    year: "2-digit",
  }).format(date);
};

const getStatusBorderClass = (status?: string) => {
  switch (status?.toLowerCase()) {
    case "active":
      return "border-emerald-500/90";
    case "pending":
      return "border-amber-400/95";
    case "sold":
      return "border-slate-300/95";
    case "prospective":
      return "border-blue-400/90";
    default:
      return "border-border/80";
  }
};

const getStatusGlowClass = (status?: string) => {
  switch (status?.toLowerCase()) {
    case "active":
      return "group-hover:shadow-[0_0_0_1px_rgba(16,185,129,0.9),0_0_28px_rgba(16,185,129,0.4)]";
    case "pending":
      return "group-hover:shadow-[0_0_0_1px_rgba(251,191,36,0.95),0_0_28px_rgba(251,191,36,0.38)]";
    case "sold":
      return "group-hover:shadow-[0_0_0_1px_rgba(203,213,225,0.95),0_0_28px_rgba(148,163,184,0.32)]";
    case "prospective":
      return "group-hover:shadow-[0_0_0_1px_rgba(96,165,250,0.95),0_0_28px_rgba(96,165,250,0.4)]";
    default:
      return "group-hover:shadow-[0_0_0_1px_rgba(255,255,255,0.2),0_0_24px_rgba(15,23,42,0.18)]";
  }
};

const getCompactAddress = (address?: string, city?: string) => {
  if (!address) return "";
  const parts = address
    .split(",")
    .map((part) => part.trim())
    .filter(Boolean);
  let result = parts.length >= 2 ? `${parts[0]}, ${parts[1]}` : address;
  if (city && !result.toLowerCase().includes(city.toLowerCase())) {
    result += `, ${city}`;
  }
  return result;
};

export const ListingCard = (props: { record?: ListingView }) => {
  const createPath = useCreatePath();
  const record = useRecordContext<ListingView>(props);
  if (!record) return null;
  const hasThumbnail = Boolean(record.thumbnail_url);
  const expiration = formatExpiration(record.listing_expiration);
  const compactAddress = getCompactAddress(
    record.unparsed_address,
    record.city,
  );

  return (
    <Link
      to={createPath({
        resource: "listings",
        id: record.id,
        type: "show",
      })}
      className="no-underline"
    >
      <Card
        className={cn(
          "group relative h-[200px] overflow-hidden border-[3px] shadow-[0_10px_30px_rgba(0,0,0,0.18)] transition-shadow duration-250",
          getStatusBorderClass(record.standard_status),
          getStatusGlowClass(record.standard_status),
        )}
      >
        {hasThumbnail ? (
          <>
            <img
              src={record.thumbnail_url}
              alt={compactAddress}
              loading="lazy"
              decoding="async"
              className="absolute inset-0 w-full h-full object-cover transition-transform duration-500 group-hover:scale-105"
            />
            <div className="absolute inset-0 bg-linear-to-b from-black/5 via-black/25 to-black/75" />
          </>
        ) : (
          <div className="absolute inset-0 bg-linear-to-br from-muted via-background to-muted/70" />
        )}
        <div className="relative flex h-full flex-col items-center px-2 pb-3 pt-2">
          <div className="flex w-full justify-center">
            <h6
              className={cn(
                "inline-block w-full max-w-[98%] rounded-xl px-3 py-1.5 text-center text-sm font-semibold leading-tight",
                hasThumbnail
                  ? "bg-black/28 text-white shadow-[0_10px_24px_rgba(0,0,0,0.22)] ring-1 ring-white/12 backdrop-blur-[6px]"
                  : "bg-background/92 text-foreground ring-1 ring-border/60",
              )}
            >
              {compactAddress}
            </h6>
          </div>

          <div className="mt-4 flex flex-col items-center gap-2.5 text-center">
            <p
              className={cn(
                "text-base font-semibold",
                hasThumbnail ? "text-white drop-shadow-sm" : "text-primary",
              )}
            >
              {new Intl.NumberFormat("en-US", {
                style: "currency",
                currency: "USD",
                maximumFractionDigits: 0,
              }).format(record.list_price)}
            </p>
            <div className="flex flex-wrap items-center justify-center gap-2">
              {expiration ? (
                <p
                  className={cn(
                    "inline-block rounded-full px-2.5 py-1 text-sm font-semibold",
                    hasThumbnail
                      ? "bg-black/24 text-white/90 ring-1 ring-white/12"
                      : "bg-muted text-muted-foreground",
                  )}
                >
                  {expiration}
                </p>
              ) : null}
            </div>
          </div>

          <div className="mt-auto flex w-full flex-row items-center justify-between gap-2">
            <div className="flex items-center">
              {record.nb_contacts ? (
                <ReferenceManyField reference="contacts" target="listing_id">
                  <AvatarGroupIterator />
                </ReferenceManyField>
              ) : null}
            </div>
            {record.nb_deals ? (
              <div className="ml-2 flex items-center gap-0.5">
                <DollarSign
                  className={cn(
                    "h-4 w-4",
                    hasThumbnail ? "text-white/80" : "text-muted-foreground",
                  )}
                />
                <span
                  className={cn(
                    "text-sm font-medium",
                    hasThumbnail && "text-white",
                  )}
                >
                  {record.nb_deals}
                </span>
                <span
                  className={cn(
                    "text-xs",
                    hasThumbnail ? "text-white/80" : "text-muted-foreground",
                  )}
                >
                  {record.nb_deals
                    ? record.nb_deals > 1
                      ? "deals"
                      : "deal"
                    : "deal"}
                </span>
              </div>
            ) : null}
          </div>
        </div>
      </Card>
    </Link>
  );
};

const AvatarGroupIterator = () => {
  const { data, total, error, isPending } = useListContext();
  if (isPending || error) return null;

  const MAX_AVATARS = 3;
  return (
    <div className="*:data-[slot=avatar]:ring-background flex -space-x-0.5 *:data-[slot=avatar]:ring-2 *:data-[slot=avatar]:grayscale-50">
      {data.slice(0, MAX_AVATARS).map((record: any) => (
        <ContactAvatar
          key={record.id}
          record={record}
          width={25}
          height={25}
          title={`${record.first_name} ${record.last_name}`}
        />
      ))}
      {total > MAX_AVATARS && (
        <span
          className="relative flex size-8 shrink-0 overflow-hidden rounded-full w-[25px] h-[25px]"
          data-slot="avatar"
        >
          <span className="bg-muted flex size-full items-center justify-center rounded-full text-[10px]">
            +{total - MAX_AVATARS}
          </span>
        </span>
      )}
    </div>
  );
};
