import { useEffect, useState } from "react";

import { ATTACHMENTS_BUCKET, PUBLIC_ASSETS_BUCKET } from "./attachments";

// Object keys are extracted from a stored public `src` URL by locating the
// bucket path segment. During the bucket migration a record's `src` may still
// point at the legacy public bucket (`/attachments/`) even though we now sign
// against the private bucket (`/crm-attachments/`), so we match either segment.
// (`/attachments/` is not a substring of `/crm-attachments/` — the char before
// "attachments" there is "-", not "/" — so the order is unambiguous.)
const BUCKET_PATH_SEGMENTS = [
  `/${ATTACHMENTS_BUCKET}/`,
  `/${PUBLIC_ASSETS_BUCKET}/`,
];

const extractKeyFromPathname = (pathname: string): string | null => {
  for (const segment of BUCKET_PATH_SEGMENTS) {
    const index = pathname.lastIndexOf(segment);
    if (index < 0) {
      continue;
    }
    const key = pathname.slice(index + segment.length);
    if (key.length > 0) {
      return key;
    }
  }
  return null;
};

/**
 * Default time-to-live (in seconds) for a signed attachment URL used for
 * in-app display and download. Short-lived so that leaked links expire quickly.
 */
export const ATTACHMENT_SIGNED_URL_TTL = 3600; // 1 hour

/**
 * Time-to-live (in seconds) for a signed URL that is deliberately shared with a
 * client outside the app (e.g. pasted into an email). Long enough to remain
 * usable for a few days without making the bucket public.
 */
export const ATTACHMENT_SHARE_URL_TTL = 60 * 60 * 24 * 7; // 7 days

type AttachmentLike = {
  src?: string | null;
  path?: string | null;
};

/**
 * Resolves the storage object path for an attachment.
 *
 * New uploads persist an explicit `path`. Legacy records (and inbound-email
 * attachments created before signed URLs) may only carry a public `src` URL,
 * so we fall back to extracting the object path from that URL.
 *
 * @param attachment - Attachment record with optional `path`/`src`.
 * @returns The object path within the attachments bucket, or `null`.
 */
export const getAttachmentStoragePath = (
  attachment: AttachmentLike,
): string | null => {
  if (attachment.path && attachment.path.length > 0) {
    return attachment.path;
  }

  if (!attachment.src) {
    return null;
  }

  // Don't try to sign in-memory previews created by the file input.
  if (
    attachment.src.startsWith("blob:") ||
    attachment.src.startsWith("data:")
  ) {
    return null;
  }

  let pathname: string;
  try {
    pathname = new URL(attachment.src, "http://localhost").pathname;
  } catch {
    return null;
  }

  const path = extractKeyFromPathname(pathname);
  if (path == null) {
    return null;
  }

  try {
    return decodeURIComponent(path);
  } catch {
    return path;
  }
};

/**
 * Generates a short-lived signed URL for an attachment so that it can be
 * displayed or downloaded without the storage bucket being public.
 *
 * Falls back to the attachment's stored `src` when the path cannot be resolved
 * or signing fails (e.g. in-memory previews, or while the bucket is still
 * public during the migration).
 *
 * @param attachment - Attachment record to resolve a URL for.
 * @param expiresIn - Signed URL TTL in seconds.
 * @returns A usable URL, or `null` when none is available.
 */
export const getAttachmentSignedUrl = async (
  attachment: AttachmentLike,
  expiresIn: number = ATTACHMENT_SIGNED_URL_TTL,
): Promise<string | null> => {
  const path = getAttachmentStoragePath(attachment);
  if (path == null) {
    return attachment.src ?? null;
  }

  // Lazily import the client so merely importing this module (e.g. in unit
  // tests) doesn't instantiate a Supabase client that requires env vars.
  const { supabase } = await import("../supabase/supabase");

  const { data, error } = await supabase.storage
    .from(ATTACHMENTS_BUCKET)
    .createSignedUrl(path, expiresIn);

  if (error || !data?.signedUrl) {
    // Fall back to the stored URL (still works while the bucket is public).
    return attachment.src ?? null;
  }

  return data.signedUrl;
};

/**
 * Generates a long-lived signed URL for deliberately sharing an attachment with
 * a client outside the app.
 *
 * @param attachment - Attachment record to share.
 * @param expiresIn - Signed URL TTL in seconds (defaults to 7 days).
 * @returns A shareable URL, or `null` when none is available.
 */
export const getShareableAttachmentUrl = (
  attachment: AttachmentLike,
  expiresIn: number = ATTACHMENT_SHARE_URL_TTL,
): Promise<string | null> => getAttachmentSignedUrl(attachment, expiresIn);

/**
 * React hook returning a short-lived signed URL for an attachment.
 *
 * Returns the stored `src` synchronously as an initial value so previews don't
 * flash empty, then swaps in the signed URL once resolved. Skips signing for
 * in-memory previews (blob:/data:).
 *
 * @param attachment - Attachment record (or `undefined`).
 * @param expiresIn - Signed URL TTL in seconds.
 * @returns The URL to use for display/download, or `undefined`.
 */
export const useAttachmentUrl = (
  attachment: AttachmentLike | undefined | null,
  expiresIn: number = ATTACHMENT_SIGNED_URL_TTL,
): string | undefined => {
  const src = attachment?.src ?? undefined;
  const path = attachment ? getAttachmentStoragePath(attachment) : null;
  const [url, setUrl] = useState<string | undefined>(src);

  useEffect(() => {
    // Nothing to sign: keep the raw src (blob preview, or unresolved path).
    if (attachment == null || path == null) {
      setUrl(src);
      return;
    }

    let active = true;
    getAttachmentSignedUrl(attachment, expiresIn).then((signed) => {
      if (active) {
        setUrl(signed ?? src);
      }
    });

    return () => {
      active = false;
    };
    // Re-run when the underlying object or its source changes.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [path, src, expiresIn]);

  return url;
};
