import { ReferenceManyField } from "@/components/admin/reference-many-field";
import { ReferenceInput } from "@/components/admin/reference-input";
import { ReferenceArrayInput } from "@/components/admin/reference-array-input";
import { AutocompleteInput } from "@/components/admin/autocomplete-input";
import { AutocompleteArrayInput } from "@/components/admin/autocomplete-array-input";
import { SaveButton } from "@/components/admin/form";
import { contactOptionText } from "../misc/ContactOption";
import { Card, CardContent } from "@/components/ui/card";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { formatDistance } from "date-fns";
import {
  ShowBase,
  useListContext,
  useShowContext,
  Form,
  useUpdate,
  useNotify,
  useRecordContext,
} from "ra-core";
import {
  Link,
  Link as RouterLink,
  useMatch,
  useNavigate,
} from "react-router-dom";

import { useIsMobile } from "@/hooks/use-mobile";
import { NotesIterator } from "../notes";
import { findDealLabel } from "../deals/deal";
import { MobileContent } from "../layout/MobileContent";
import MobileHeader from "../layout/MobileHeader";
import { MobileBackButton } from "../misc/MobileBackButton";
import { useConfigurationContext } from "../root/ConfigurationContext";
import type { ListingView, Deal } from "../types";
import {
  AdditionalInfo,
  AddressInfo,
  ListingAside,
  ListingInfo,
  ContextInfo,
  ListingContactsAside,
} from "./ListingAside";
import { ListingAvatar } from "./ListingAvatar";
import { SmartTimelineIterator } from "./SmartTimeline";
import { ListingInquiriesIterator } from "./ListingInquiries";
import { ConvertProspectiveListing } from "./ConvertProspectiveListing";

export const ListingShow = () => {
  const isMobile = useIsMobile();

  return (
    <ShowBase>
      {isMobile ? <ListingShowContentMobile /> : <ListingShowContent />}
    </ShowBase>
  );
};

const ListingShowContentMobile = () => {
  const { record, isPending } = useShowContext<ListingView>();
  if (isPending || !record) return null;

  return (
    <>
      <MobileHeader>
        <MobileBackButton to="/" />
        <div className="flex flex-1">
          <Link to="/">
            <h1 className="text-xl font-semibold">Listing</h1>
          </Link>
        </div>
      </MobileHeader>

      <MobileContent>
        <div className="mb-6">
          <div className="flex items-center mb-4">
            <ListingAvatar />
            <div className="mx-3 flex-1">
              <h2 className="text-2xl font-bold">{record.unparsed_address}</h2>
            </div>
          </div>
        </div>
        <Tabs defaultValue="activity" className="w-full">
          <TabsList className="flex flex-wrap w-full h-auto justify-start">
            <TabsTrigger value="activity">Activity</TabsTrigger>
            <TabsTrigger value="timeline">Timeline</TabsTrigger>
            <TabsTrigger value="inquiries">Inquiries</TabsTrigger>
            {record.nb_deals ? (
              <TabsTrigger value="deals">
                {record.nb_deals === 1
                  ? "1 escrow"
                  : `${record.nb_deals} escrows`}
              </TabsTrigger>
            ) : null}
            <TabsTrigger value="details">Details</TabsTrigger>
          </TabsList>
          <TabsContent value="activity" className="pt-2">
            <ReferenceManyField
              target="listing_id"
              reference="listing_notes"
              sort={{ field: "date", order: "DESC" }}
              queryOptions={{
                placeholderData: null as any,
              }}
              empty={false}
            >
              <NotesIterator reference="listings" />
            </ReferenceManyField>
          </TabsContent>
          <TabsContent value="timeline" className="pt-2">
            <ReferenceManyField
              reference="listing_milestones"
              target="listing_key"
              sort={{ field: "id", order: "ASC" }}
              empty={false}
            >
              <SmartTimelineIterator />
            </ReferenceManyField>
          </TabsContent>
          <TabsContent value="inquiries" className="pt-2">
            <ReferenceManyField
              reference="listing_inquiries"
              target="listing_key"
              sort={{ field: "date", order: "DESC" }}
              empty={false}
            >
              <ListingInquiriesIterator />
            </ReferenceManyField>
          </TabsContent>
          <TabsContent value="deals">
            {record.nb_deals ? (
              <ReferenceManyField
                reference="deals"
                target="listing_id"
                sort={{ field: "name", order: "ASC" }}
              >
                <DealsIterator />
              </ReferenceManyField>
            ) : null}
          </TabsContent>
          <TabsContent value="details" className="mt-4">
            <div className="space-y-6">
              <ListingInfo record={record} />
              <AddressInfo record={record} />
              <ContextInfo record={record} />
              <AdditionalInfo record={record} />
              <ListingContactsAside record={record} />
            </div>
          </TabsContent>
        </Tabs>
      </MobileContent>
    </>
  );
};

const ListingShowContent = () => {
  const { record, isPending } = useShowContext<ListingView>();
  const navigate = useNavigate();

  // Get tab from URL or default to "activity"
  const tabMatch = useMatch("/listings/:id/show/:tab");
  const currentTab = tabMatch?.params?.tab || "activity";

  const handleTabChange = (value: string) => {
    if (value === currentTab) return;
    if (value === "activity") {
      navigate(`/listings/${record?.id}/show`);
      return;
    }
    navigate(`/listings/${record?.id}/show/${value}`);
  };

  if (isPending || !record) return null;

  return (
    <div className="mt-2 flex pb-2 gap-8">
      <div className="flex-1">
        <Card>
          <CardContent>
            <div className="flex mb-3 items-center">
              <ListingAvatar />
              <h5 className="text-xl ml-2 flex-1">{record.unparsed_address}</h5>
              {String(record.id).startsWith("PROSP-") && (
                <ConvertProspectiveListing oldKey={String(record.id)} />
              )}
            </div>
            <Tabs defaultValue={currentTab} onValueChange={handleTabChange}>
              <TabsList className="flex flex-wrap w-full h-auto justify-start">
                <TabsTrigger value="activity">Activity</TabsTrigger>
                <TabsTrigger value="timeline">Timeline</TabsTrigger>
                <TabsTrigger value="inquiries">Inquiries</TabsTrigger>
                <TabsTrigger value="contacts">Contacts</TabsTrigger>
                {record.nb_deals ? (
                  <TabsTrigger value="deals">
                    {record.nb_deals === 1
                      ? "1 escrow"
                      : `${record.nb_deals} escrows`}
                  </TabsTrigger>
                ) : null}
              </TabsList>
              <TabsContent value="activity" className="pt-2">
                <ReferenceManyField
                  target="listing_id"
                  reference="listing_notes"
                  sort={{ field: "date", order: "DESC" }}
                  queryOptions={{
                    placeholderData: null as any,
                  }}
                  empty={false}
                >
                  <NotesIterator reference="listings" />
                </ReferenceManyField>
              </TabsContent>
              <TabsContent value="timeline" className="pt-2">
                <ReferenceManyField
                  reference="listing_milestones"
                  target="listing_key"
                  sort={{ field: "id", order: "ASC" }}
                  empty={false}
                >
                  <SmartTimelineIterator />
                </ReferenceManyField>
              </TabsContent>
              <TabsContent value="inquiries" className="pt-2">
                <ReferenceManyField
                  reference="listing_inquiries"
                  target="listing_key"
                  sort={{ field: "date", order: "DESC" }}
                  empty={false}
                >
                  <ListingInquiriesIterator />
                </ReferenceManyField>
              </TabsContent>
              <TabsContent value="contacts" className="pt-4">
                <ListingContactsForm />
              </TabsContent>
              <TabsContent value="deals">
                {record.nb_deals ? (
                  <ReferenceManyField
                    reference="deals"
                    target="listing_id"
                    sort={{ field: "name", order: "ASC" }}
                  >
                    <DealsIterator />
                  </ReferenceManyField>
                ) : null}
              </TabsContent>
            </Tabs>
          </CardContent>
        </Card>
      </div>
      <ListingAside />
    </div>
  );
};

const DealsIterator = () => {
  const { data: deals, error, isPending } = useListContext<Deal>();
  const { dealStages, dealCategories } = useConfigurationContext();
  if (isPending || error) return null;

  const now = Date.now();
  return (
    <div>
      <div>
        {deals.map((deal) => (
          <div key={deal.id} className="p-0 text-sm">
            <RouterLink
              to={`/deals/${deal.id}/show`}
              className="flex items-center justify-between hover:bg-muted py-2 px-4 transition-colors"
            >
              <div className="flex-1 min-w-0">
                <div className="font-medium">{deal.name}</div>
                <div className="text-sm text-muted-foreground">
                  {findDealLabel(dealStages, deal.stage)},{" "}
                  {deal.amount.toLocaleString("en-US", {
                    notation: "compact",
                    style: "currency",
                    currency: "USD",
                    currencyDisplay: "narrowSymbol",
                    minimumSignificantDigits: 3,
                  })}
                  {deal.category
                    ? `, ${dealCategories.find((c) => c.value === deal.category)?.label ?? deal.category}`
                    : ""}
                </div>
              </div>
              <div className="text-right">
                <div className="text-sm text-muted-foreground">
                  last activity {formatDistance(deal.updated_at, now)} ago{" "}
                </div>
              </div>
            </RouterLink>
          </div>
        ))}
      </div>
    </div>
  );
};

const ListingContactsForm = () => {
  const record = useRecordContext<ListingView>();
  const [update] = useUpdate();
  const notify = useNotify();

  if (!record) return null;

  const handleSubmit = async (data: any) => {
    await update("listings", {
      id: record.id,
      data,
      previousData: record,
    });
    notify("Contacts updated successfully", { type: "success" });
  };

  return (
    <Form
      record={record}
      onSubmit={handleSubmit}
      className="flex flex-col gap-6 w-full max-w-2xl"
    >
      <div className="flex flex-col gap-2">
        <h3 className="font-semibold text-lg">Primary Seller</h3>
        <ReferenceInput
          source="seller_id"
          reference="contacts_summary"
          helperText={false}
        >
          <AutocompleteInput
            label="Select Primary Seller"
            helperText={false}
            optionText={contactOptionText}
            className="w-full"
          />
        </ReferenceInput>
      </div>

      <div className="flex flex-col gap-2 border-t pt-6">
        <h3 className="font-semibold text-lg">Other Contacts</h3>
        <ReferenceArrayInput
          source="contact_ids"
          reference="contacts_summary"
          helperText={false}
        >
          <AutocompleteArrayInput
            label="Select Other Contacts"
            optionText={contactOptionText}
            helperText={false}
            className="w-full"
          />
        </ReferenceArrayInput>
      </div>

      <div className="flex justify-end pt-4">
        <SaveButton label="Save Contacts" />
      </div>
    </Form>
  );
};
