import { address, datatype, lorem, random } from "faker/locale/en_US";
import { randomDate } from "./utils";
import type { Db } from "./types";
import type { ListingView, RAFile } from "../../../types";

const listingStatuses = ["Active", "Pending", "Closed", "Withdrawn"] as const;

export const generateListings = (
  db: Db,
  size = 30,
): Required<ListingView>[] => {
  return Array.from(Array(size).keys()).map((id) => {
    const status = random.arrayElement(listingStatuses);
    const listPrice = datatype.number({ min: 250000, max: 3000000 });
    const createdAt = randomDate();
    const daysOnMarket = datatype.number({ min: 3, max: 120 });
    const city = address.city();

    return {
      id,
      supplement_id: id,
      listing_key: datatype.uuid(),
      listing_id: `L-${String(1000 + id)}`,
      standard_status: status,
      list_price: listPrice,
      close_price:
        status === "Closed"
          ? Math.round(listPrice * (0.96 + Math.random() * 0.06))
          : undefined,
      unparsed_address: address.streetAddress(),
      city,
      list_agent_full_name: `${random.arrayElement(db.sales).first_name} ${random.arrayElement(db.sales).last_name}`,
      thumbnail_url: `https://picsum.photos/seed/listing-${id}/600/400`,
      days_on_market: daysOnMarket,
      seller_id: random.arrayElement(db.contacts).id,
      sales_id: datatype.number(2) === 0 ? 0 : random.arrayElement(db.sales).id,
      created_at: createdAt.toISOString(),
      updated_at: randomDate(createdAt).toISOString(),
      listing_expiration: randomDate().toISOString(),
      lockbox_serial: random.alphaNumeric(6).toUpperCase(),
      flyer_file_path: "",
      showing_instructions: lorem.sentence(),
      contact_ids: datatype.boolean()
        ? [random.arrayElement(db.contacts).id]
        : [],
      nb_contacts: datatype.boolean() ? 1 : 0,
      nb_deals: datatype.number({ min: 0, max: 2 }),
      thumbnail: undefined as unknown as RAFile,
    };
  });
};
