import {
  useRecordContext,
  useGetList,
  useCreate,
  useDelete,
  useNotify,
  useGetMany,
  type Identifier,
} from "ra-core";
import { useState, useMemo, useEffect } from "react";
import { Plus, X, Check, ChevronsUpDown } from "lucide-react";

import { Button } from "@/components/ui/button";
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from "@/components/ui/command";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Input } from "@/components/ui/input";
import { cn } from "@/lib/utils";

import type { Contact, ContactConnection } from "../types";

const PREDEFINED_LABELS = ["Parent", "Child", "Sibling", "Spouse", "Friend"];

export const ContactConnectionsInput = () => {
  const record = useRecordContext<Contact>();

  if (!record?.id) {
    return (
      <div className="flex flex-col gap-4">
        <h6 className="text-lg font-semibold">Connections</h6>
        <p className="text-sm text-muted-foreground italic">
          Save the contact first to add connections
        </p>
      </div>
    );
  }

  return <ConnectionsManager contactId={record.id} />;
};

const ConnectionsManager = ({ contactId }: { contactId: Identifier }) => {
  const notify = useNotify();
  const [create] = useCreate();
  const [deleteOne] = useDelete();
  const [showAddForm, setShowAddForm] = useState(false);

  const {
    data: connections,
    isPending,
    refetch,
  } = useGetList<ContactConnection>("contact_connections", {
    filter: { contact_id: contactId },
    sort: { field: "label", order: "ASC" },
    pagination: { page: 1, perPage: 50 },
  });

  // Collect all unique contact IDs we need to fetch
  const linkedContactIds =
    connections?.map((conn) =>
      conn.contact_id_a === contactId ? conn.contact_id_b : conn.contact_id_a,
    ) ?? [];

  const { data: linkedContacts } = useGetMany<Contact>(
    "contacts",
    { ids: linkedContactIds },
    { enabled: linkedContactIds.length > 0 },
  );

  const contactMap = new Map(linkedContacts?.map((c) => [c.id, c]));

  const handleAdd = async (selectedContactId: Identifier, label: string) => {
    try {
      await create(
        "contact_connections",
        {
          data: {
            contact_id_a: contactId,
            contact_id_b: selectedContactId,
            label,
            created_at: new Date().toISOString(),
          },
        },
        { returnPromise: true },
      );
      setShowAddForm(false);
      refetch();
      notify("Connection added", { type: "success" });
    } catch {
      notify("Failed to add connection", { type: "error" });
    }
  };

  const handleDelete = async (connection: ContactConnection) => {
    try {
      await deleteOne(
        "contact_connections",
        { id: connection.id, previousData: connection },
        { returnPromise: true },
      );
      refetch();
      notify("Connection removed", { type: "success" });
    } catch {
      notify("Failed to remove connection", { type: "error" });
    }
  };

  if (isPending) {
    return (
      <div className="flex flex-col gap-4">
        <h6 className="text-lg font-semibold">Connections</h6>
        <p className="text-sm text-muted-foreground">Loading...</p>
      </div>
    );
  }

  return (
    <div className="flex flex-col gap-4">
      <h6 className="text-lg font-semibold">Connections</h6>

      {connections && connections.length > 0 && (
        <div className="flex flex-col gap-2">
          {connections.map((connection) => {
            const linkedId =
              connection.contact_id_a === contactId
                ? connection.contact_id_b
                : connection.contact_id_a;
            const linkedContact = contactMap.get(linkedId);

            return (
              <div
                key={connection.id}
                className="flex items-center justify-between p-2 border rounded-md bg-muted/30"
              >
                <div className="flex items-center gap-2 min-w-0">
                  <span className="text-sm truncate">
                    {linkedContact
                      ? `${linkedContact.first_name} ${linkedContact.last_name}`
                      : "Loading..."}
                  </span>
                  <span className="text-xs text-muted-foreground shrink-0">
                    ({connection.label})
                  </span>
                </div>
                <Button
                  type="button"
                  variant="ghost"
                  size="sm"
                  onClick={() => handleDelete(connection)}
                  className="h-6 w-6 p-0 shrink-0"
                >
                  <X className="w-4 h-4" />
                </Button>
              </div>
            );
          })}
        </div>
      )}

      {showAddForm ? (
        <AddConnectionForm
          currentContactId={contactId}
          existingConnectionIds={linkedContactIds}
          onAdd={handleAdd}
          onCancel={() => setShowAddForm(false)}
        />
      ) : (
        <Button
          type="button"
          variant="outline"
          size="sm"
          onClick={() => setShowAddForm(true)}
          className="w-fit"
        >
          <Plus className="w-4 h-4 mr-1" />
          Add Connection
        </Button>
      )}
    </div>
  );
};

const AddConnectionForm = ({
  currentContactId,
  existingConnectionIds,
  onAdd,
  onCancel,
}: {
  currentContactId: Identifier;
  existingConnectionIds: Identifier[];
  onAdd: (contactId: Identifier, label: string) => void;
  onCancel: () => void;
}) => {
  const [selectedContact, setSelectedContact] = useState<Contact | null>(null);
  const [selectedLabel, setSelectedLabel] = useState<string>("");
  const [customLabel, setCustomLabel] = useState<string>("");
  const [contactPickerOpen, setContactPickerOpen] = useState(false);

  // Server-side search for contacts as the user types
  const [searchText, setSearchText] = useState("");
  const [debouncedSearch, setDebouncedSearch] = useState("");

  useEffect(() => {
    const timer = setTimeout(() => setDebouncedSearch(searchText), 300);
    return () => clearTimeout(timer);
  }, [searchText]);

  const { data: allContacts } = useGetList<Contact>("contacts_summary", {
    sort: { field: "last_name", order: "ASC" },
    filter: debouncedSearch ? { q: debouncedSearch } : {},
    pagination: { page: 1, perPage: 25 },
  });

  // Filter out current contact and already connected contacts
  const excludeIds = useMemo(
    () => new Set([currentContactId, ...existingConnectionIds]),
    [currentContactId, existingConnectionIds],
  );

  const availableContacts = useMemo(
    () => allContacts?.filter((c) => !excludeIds.has(c.id)) ?? [],
    [allContacts, excludeIds],
  );

  const handleSubmit = () => {
    const finalLabel =
      selectedLabel === "_custom" ? customLabel : selectedLabel;
    if (selectedContact && finalLabel) {
      onAdd(selectedContact.id, finalLabel);
    }
  };

  const isValid =
    selectedContact &&
    (selectedLabel === "_custom" ? customLabel.trim() : selectedLabel);

  return (
    <div className="flex flex-col gap-3 p-3 border rounded-md bg-muted/20">
      <div className="flex flex-col gap-2">
        <label className="text-sm font-medium">Contact</label>
        <Popover open={contactPickerOpen} onOpenChange={setContactPickerOpen}>
          <PopoverTrigger asChild>
            <Button
              variant="outline"
              role="combobox"
              aria-expanded={contactPickerOpen}
              className="justify-between font-normal"
            >
              {selectedContact
                ? `${selectedContact.first_name} ${selectedContact.last_name}`
                : "Select a contact..."}
              <ChevronsUpDown className="ml-2 h-4 w-4 shrink-0 opacity-50" />
            </Button>
          </PopoverTrigger>
          <PopoverContent className="w-[300px] p-0" align="start">
            <Command shouldFilter={false}>
              <CommandInput
                placeholder="Search contacts..."
                value={searchText}
                onValueChange={setSearchText}
              />
              <CommandList>
                <CommandEmpty>No contacts found.</CommandEmpty>
                <CommandGroup>
                  {availableContacts.map((contact) => (
                    <CommandItem
                      key={contact.id}
                      value={`${contact.first_name} ${contact.last_name}`}
                      onSelect={() => {
                        setSelectedContact(contact);
                        setContactPickerOpen(false);
                      }}
                    >
                      <Check
                        className={cn(
                          "mr-2 h-4 w-4",
                          selectedContact?.id === contact.id
                            ? "opacity-100"
                            : "opacity-0",
                        )}
                      />
                      {contact.first_name} {contact.last_name}
                    </CommandItem>
                  ))}
                </CommandGroup>
              </CommandList>
            </Command>
          </PopoverContent>
        </Popover>
      </div>

      <div className="flex flex-col gap-2">
        <label className="text-sm font-medium">Relationship</label>
        <Select value={selectedLabel} onValueChange={setSelectedLabel}>
          <SelectTrigger>
            <SelectValue placeholder="Select relationship..." />
          </SelectTrigger>
          <SelectContent>
            {PREDEFINED_LABELS.map((label) => (
              <SelectItem key={label} value={label}>
                {label}
              </SelectItem>
            ))}
            <SelectItem value="_custom">Custom...</SelectItem>
          </SelectContent>
        </Select>
        {selectedLabel === "_custom" && (
          <Input
            placeholder="Enter custom relationship..."
            value={customLabel}
            onChange={(e) => setCustomLabel(e.target.value)}
            className="mt-1"
          />
        )}
      </div>

      <div className="flex gap-2 mt-1">
        <Button
          type="button"
          size="sm"
          onClick={handleSubmit}
          disabled={!isValid}
        >
          Add Connection
        </Button>
        <Button type="button" size="sm" variant="outline" onClick={onCancel}>
          Cancel
        </Button>
      </div>
    </div>
  );
};
