import { useGetList, useGetMany, useRecordContext } from "ra-core";
import { Link } from "react-router-dom";
import { Link2 } from "lucide-react";

import type { Contact, ContactConnection } from "../types";

export const ContactConnections = () => {
  const record = useRecordContext<Contact>();

  if (!record) return null;

  return <ConnectionsList contactId={record.id} />;
};

const ConnectionsList = ({ contactId }: { contactId: Contact["id"] }) => {
  const { data: connections, isPending: connectionsLoading } =
    useGetList<ContactConnection>("contact_connections", {
      filter: { contact_id: contactId },
      sort: { field: "label", order: "ASC" },
      pagination: { page: 1, perPage: 50 },
    });

  // Collect all unique contact IDs we need to fetch (the "other" contact in each connection)
  const linkedContactIds =
    connections?.map((conn) =>
      conn.contact_id_a === contactId ? conn.contact_id_b : conn.contact_id_a,
    ) ?? [];

  const { data: linkedContacts, isPending: contactsLoading } =
    useGetMany<Contact>(
      "contacts",
      { ids: linkedContactIds },
      { enabled: linkedContactIds.length > 0 },
    );

  if (connectionsLoading) {
    return (
      <p className="text-sm text-muted-foreground">Loading connections...</p>
    );
  }

  if (!connections || connections.length === 0) {
    return null;
  }

  if (contactsLoading) {
    return (
      <p className="text-sm text-muted-foreground">Loading connections...</p>
    );
  }

  // Create a map for quick lookup
  const contactMap = new Map(linkedContacts?.map((c) => [c.id, c]));

  return (
    <div className="flex flex-col gap-1">
      {connections.map((connection) => {
        const linkedId =
          connection.contact_id_a === contactId
            ? connection.contact_id_b
            : connection.contact_id_a;
        const linkedContact = contactMap.get(linkedId);

        if (!linkedContact) return null;

        return (
          <div key={connection.id} className="flex items-center gap-2">
            <Link2 className="w-3.5 h-3.5 text-muted-foreground shrink-0" />
            <Link
              to={`/contacts/${linkedId}/show`}
              className="text-sm underline hover:no-underline text-primary truncate"
            >
              {linkedContact.first_name} {linkedContact.last_name}
            </Link>
            <span className="text-xs text-muted-foreground shrink-0">
              ({connection.label})
            </span>
          </div>
        );
      })}
    </div>
  );
};
