import { useState } from "react";
import { MessageSquare, Pencil, Star, CircleX, Save } from "lucide-react";
import {
  useListContext,
  useUpdate,
  Form,
  RecordContextProvider,
} from "ra-core";
import { formatDistanceToNow } from "date-fns";
import { DeleteButton } from "@/components/admin/delete-button";
import { Button } from "@/components/ui/button";
import { SelectInput } from "@/components/admin/select-input";
import { TextInput } from "@/components/admin/text-input";
import { NumberInput } from "@/components/admin/number-input";
import { DateInput } from "@/components/admin/date-input";

import type { ListingInquiry } from "../types";

import { ListingInquiryCreate } from "./ListingInquiryCreate";
import { AddSectionContainer } from "../misc/AddSectionContainer";

export const ListingInquiriesIterator = () => {
  const { data: inquiries, isPending } = useListContext<ListingInquiry>();

  if (isPending || !inquiries) return null;

  return (
    <div className="pt-4 flex flex-col gap-4">
      <AddSectionContainer label="Add an inquiry" defaultOpen={false}>
        <ListingInquiryCreate />
      </AddSectionContainer>
      {inquiries.length === 0 ? (
        <p className="text-sm text-muted-foreground pt-4">
          No inquiries or feedback yet.
        </p>
      ) : (
        inquiries.map((inquiry) => (
          <ListingInquiryCard key={inquiry.id} inquiry={inquiry} />
        ))
      )}
    </div>
  );
};

const ListingInquiryCard = ({ inquiry }: { inquiry: ListingInquiry }) => {
  const [isEditing, setEditing] = useState(false);
  const [update, { isPending }] = useUpdate();
  const { refetch } = useListContext<ListingInquiry>();

  const handleSubmit = (values: Partial<ListingInquiry>) => {
    update(
      "listing_inquiries",
      { id: inquiry.id, data: values, previousData: inquiry },
      {
        onSuccess: () => {
          setEditing(false);
          refetch();
        },
      },
    );
  };

  if (isEditing) {
    return (
      <div className="p-3 border rounded-lg bg-card shadow-sm">
        <Form record={inquiry} onSubmit={handleSubmit}>
          <div className="flex gap-4">
            <SelectInput
              source="type"
              choices={[
                { id: "Inquiry", name: "Inquiry" },
                { id: "Feedback", name: "Feedback" },
              ]}
              className="w-1/3"
            />
            <TextInput source="name" label="Name" className="flex-1" />
          </div>
          <div className="flex gap-4">
            <TextInput source="email" className="flex-1" />
            <TextInput source="phone" className="flex-1" />
            <NumberInput source="rating" min={0} max={5} className="w-1/4" />
            <DateInput source="date" label="Date" className="w-1/4" />
          </div>
          <TextInput source="comments" multiline className="w-full" />
          <div className="flex justify-end gap-2 mt-2">
            <Button
              type="button"
              variant="ghost"
              onClick={() => setEditing(false)}
            >
              <CircleX className="w-4 h-4" />
              Cancel
            </Button>
            <Button type="submit" disabled={isPending}>
              <Save className="w-4 h-4" />
              Save
            </Button>
          </div>
        </Form>
      </div>
    );
  }

  return (
    <div className="p-3 border rounded-lg bg-card shadow-sm flex flex-col relative group">
      <div className="absolute top-2 right-2 flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
        <Button
          type="button"
          size="icon"
          variant="ghost"
          onClick={() => setEditing(true)}
          className="h-8 w-8 text-muted-foreground hover:bg-accent hover:text-foreground p-0"
        >
          <Pencil className="h-4 w-4" />
        </Button>
        <RecordContextProvider value={inquiry}>
          <DeleteButton
            resource="listing_inquiries"
            redirect={false}
            size="icon"
            variant="ghost"
            label=""
            className="h-8 w-8 text-muted-foreground hover:bg-destructive/10 hover:text-destructive p-0"
          />
        </RecordContextProvider>
      </div>
      <div className="flex justify-between items-start mb-2 pr-16">
        <div className="flex flex-wrap items-center gap-2">
          <MessageSquare className="h-4 w-4 text-primary" />
          <h6 className="font-medium text-sm">{inquiry.name}</h6>
          <span className="text-[10px] bg-secondary text-secondary-foreground px-1.5 py-0.5 rounded uppercase font-semibold">
            {inquiry.type}
          </span>
        </div>
        <span className="text-xs text-muted-foreground">
          {formatDistanceToNow(new Date(inquiry.date), {
            addSuffix: true,
          })}
        </span>
      </div>

      <div className="text-xs text-muted-foreground space-y-1 mb-2">
        <div>
          Email:{" "}
          <a
            href={`mailto:${inquiry.email}`}
            className="text-primary hover:underline"
          >
            {inquiry.email}
          </a>
        </div>
        <div>
          Phone:{" "}
          <a
            href={`tel:${inquiry.phone}`}
            className="text-primary hover:underline"
          >
            {inquiry.phone}
          </a>
        </div>
      </div>

      <p className="text-sm bg-muted/50 p-2 rounded text-foreground">
        {inquiry.comments}
      </p>

      {inquiry.rating && (
        <div className="mt-2 flex items-center gap-1.5">
          <span className="text-xs font-medium text-muted-foreground">
            Rating:
          </span>
          <div className="flex">
            {[1, 2, 3, 4, 5].map((star) => (
              <Star
                key={star}
                className={`h-3.5 w-3.5 ${star <= (inquiry.rating ?? 0) ? "text-yellow-500 fill-yellow-500" : "text-muted"}`}
              />
            ))}
          </div>
        </div>
      )}
    </div>
  );
};
