import { add, sub } from "date-fns";
import { datatype, lorem, random } from "faker/locale/en_US";
import {
  defaultDealCategories,
  defaultDealStages,
  defaultEscrowMilestones,
} from "../../../root/defaultConfiguration";
import type { Deal, EscrowMilestone } from "../../../types";
import type { Db } from "./types";
import { randomDate } from "./utils";

const ACTIVE_ESCROW_STAGES = ["contingency", "clear-to-close"];
const REPRESENTATIONS = ["buyer", "seller", "both"] as const;

const generateMilestones = (
  acceptanceDate: Date,
  _closingDate: Date,
): EscrowMilestone[] => {
  return defaultEscrowMilestones.map((template) => {
    const milestone: EscrowMilestone = {
      id: crypto.randomUUID(),
      ...template,
    };
    // Randomly mark some milestones as completed for realism
    if (milestone.enabled && milestone.reference_point === "acceptance") {
      const dueDate = add(acceptanceDate, { days: milestone.days_offset });
      if (dueDate < new Date() && datatype.boolean()) {
        milestone.completed_at = add(dueDate, {
          days: datatype.number({ min: -1, max: 2 }),
        }).toISOString();
      }
    }
    return milestone;
  });
};

export const generateDeals = (db: Db): Deal[] => {
  const deals = Array.from(Array(50).keys()).map((id) => {
    const company = random.arrayElement(db.companies);
    const contacts = random.arrayElements(
      db.contacts.filter((contact) => contact.company_id === company.id),
      datatype.number({ min: 1, max: 3 }),
    );
    const lowercaseName = lorem.words();
    const created_at = randomDate(new Date(company.created_at)).toISOString();

    const expected_closing_date = randomDate(
      new Date(created_at),
      add(new Date(created_at), { months: 6 }),
    )
      .toISOString()
      .split("T")[0];

    const stage = random.arrayElement(defaultDealStages).value;
    if (stage !== "closed" && stage !== "cancelled") {
      company.nb_deals++;
    }
    const isActiveEscrow = ACTIVE_ESCROW_STAGES.includes(stage);

    // For active escrows, generate realistic escrow fields
    const closingDate = new Date(expected_closing_date);
    const escrowDays = datatype.number({ min: 30, max: 60 });
    const acceptanceDate = isActiveEscrow
      ? sub(closingDate, { days: escrowDays })
      : undefined;

    return {
      id,
      name: lowercaseName[0].toUpperCase() + lowercaseName.slice(1),
      company_id: company.id,
      contact_ids: contacts.map((contact) => contact.id),
      category: random.arrayElement(defaultDealCategories).value,
      stage,
      description: lorem.paragraphs(datatype.number({ min: 1, max: 4 })),
      amount: datatype.number(1000) * 100,
      created_at,
      updated_at: randomDate(new Date(created_at)).toISOString(),
      expected_closing_date,
      sales_id: company.sales_id,
      index: 0,
      ...(isActiveEscrow && acceptanceDate
        ? {
            acceptance_date: acceptanceDate.toISOString(),
            representation: random.arrayElement([...REPRESENTATIONS]),
            milestones: generateMilestones(acceptanceDate, closingDate),
          }
        : {}),
    };
  });
  // compute index based on stage
  defaultDealStages.forEach((stage) => {
    deals
      .filter((deal) => deal.stage === stage.value)
      .forEach((deal, index) => {
        deals[deal.id].index = index;
      });
  });
  return deals;
};
