import { useState } from "react";
import { useDataProvider, useNotify, useRefresh } from "ra-core";
import { useNavigate } from "react-router-dom";
import { ArrowRightCircle } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import type { CrmDataProvider } from "../providers/supabase/dataProvider";

export const ConvertProspectiveListing = ({ oldKey }: { oldKey: string }) => {
  const [open, setOpen] = useState(false);
  const [newKey, setNewKey] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const dataProvider = useDataProvider<CrmDataProvider>();
  const notify = useNotify();
  const navigate = useNavigate();
  const refresh = useRefresh();

  const handleConvert = async () => {
    const trimmed = newKey.trim();
    if (!trimmed) return;
    setSubmitting(true);
    try {
      await dataProvider.convertProspectiveListing(oldKey, trimmed);
      notify("Listing converted to active", { type: "success" });
      setOpen(false);
      navigate(`/listings/${encodeURIComponent(trimmed)}/show`);
      refresh();
    } catch (err: any) {
      notify(err?.message ?? "Failed to convert listing", { type: "error" });
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <>
      <Button
        type="button"
        variant="outline"
        size="sm"
        onClick={() => setOpen(true)}
      >
        <ArrowRightCircle className="h-4 w-4 mr-1" />
        Convert to Active
      </Button>
      <Dialog open={open} onOpenChange={setOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Convert to active listing</DialogTitle>
            <DialogDescription>
              Enter the MLS listing key for the live listing. Notes, contacts,
              files, and milestones from this prospective record will be moved
              to the MLS listing, and the prospective record will be deleted.
            </DialogDescription>
          </DialogHeader>
          <div className="space-y-2 py-2">
            <label className="text-sm font-medium" htmlFor="mls-listing-key">
              MLS listing key
            </label>
            <Input
              id="mls-listing-key"
              value={newKey}
              onChange={(e) => setNewKey(e.target.value)}
              placeholder="e.g. PI24123456"
              autoFocus
            />
          </div>
          <DialogFooter>
            <Button
              type="button"
              variant="ghost"
              onClick={() => setOpen(false)}
              disabled={submitting}
            >
              Cancel
            </Button>
            <Button
              type="button"
              onClick={handleConvert}
              disabled={!newKey.trim() || submitting}
            >
              {submitting ? "Converting…" : "Convert"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  );
};
