import { format, parseISO } from "date-fns";
import { Briefcase, Calendar, Clock, MapPin } from "lucide-react";
import { useGetList } from "ra-core";
import { memo, useMemo } from "react";
import { Link } from "react-router";

import { Badge } from "@/components/ui/badge";
import { Card } from "@/components/ui/card";
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip";

import type { Deal, EscrowMilestone } from "../types";
import {
  calculateMilestoneDate,
  getEscrowProgress,
  getMilestonePosition,
  getMilestoneStatus,
} from "./escrowTimelineUtils";

const formatAmount = (amount: number) =>
  amount.toLocaleString("en-US", {
    notation: "compact",
    style: "currency",
    currency: "USD",
    currencyDisplay: "narrowSymbol",
    minimumSignificantDigits: 3,
  });

const MilestoneDot = ({
  milestone,
  acceptanceDate,
  closingDate,
}: {
  milestone: EscrowMilestone;
  acceptanceDate: string;
  closingDate: string;
}) => {
  const date = calculateMilestoneDate(milestone, acceptanceDate, closingDate);
  if (!date) return null;

  const position = getMilestonePosition(date, acceptanceDate, closingDate);
  const status = getMilestoneStatus(milestone, date);

  const colorClass = status === "overdue" ? "bg-red-500" : "bg-blue-500";

  return (
    <Tooltip>
      <TooltipTrigger asChild>
        <div
          className={`absolute top-1/2 -translate-y-1/2 -translate-x-1/2 w-2.5 h-2.5 rounded-full ${colorClass} border border-background cursor-default z-10`}
          style={{ left: `${position}%` }}
          aria-label={`${milestone.name}: ${format(date, "MMM d")}`}
        />
      </TooltipTrigger>
      <TooltipContent side="top" className="text-xs">
        <div className="font-medium">{milestone.name}</div>
        <div className="text-primary-foreground/70">
          {format(date, "MMM d, yyyy")}
          {milestone.rpa_reference && ` · ${milestone.rpa_reference}`}
        </div>
        {status === "completed" && (
          <div className="text-green-300">Completed</div>
        )}
        {status === "overdue" && <div className="text-red-300">Overdue</div>}
      </TooltipContent>
    </Tooltip>
  );
};

const EscrowTimelineCard = ({ deal }: { deal: Deal }) => {
  const acceptanceDate = deal.acceptance_date!.slice(0, 10);
  const closingDate = deal.expected_closing_date.slice(0, 10);

  const progress = useMemo(
    () => getEscrowProgress(acceptanceDate, closingDate),
    [acceptanceDate, closingDate],
  );

  const enabledMilestones = useMemo(
    () => (deal.milestones ?? []).filter((m) => m.enabled),
    [deal.milestones],
  );

  const completedCount = enabledMilestones.filter((m) => m.completed_at).length;

  // Find the position of the earliest overdue (incomplete) milestone
  const firstOverduePosition = useMemo(() => {
    const now = new Date();
    let earliest: number | null = null;
    for (const m of enabledMilestones) {
      if (m.completed_at) continue;
      const date = calculateMilestoneDate(m, acceptanceDate, closingDate);
      if (date != null && date < now) {
        const pos = getMilestonePosition(date, acceptanceDate, closingDate);
        if (earliest === null || pos < earliest) earliest = pos;
      }
    }
    return earliest;
  }, [enabledMilestones, acceptanceDate, closingDate]);

  const formatDate = (dateStr: string) => {
    const d = parseISO(dateStr);
    return format(d, "MMM d");
  };

  return (
    <Link to={`/deals/${deal.id}/show`} className="block no-underline">
      <Card className="p-4 gap-3 flex flex-col hover:border-primary/50 transition-colors cursor-pointer">
        {/* Header */}
        <div className="flex items-start justify-between gap-2">
          <div className="flex items-center gap-2 min-w-0">
            <MapPin className="w-4 h-4 text-muted-foreground shrink-0" />
            <span className="font-semibold text-sm truncate" title={deal.name}>
              {deal.name}
            </span>
          </div>
          <div className="flex items-center gap-2 shrink-0">
            {progress.isOverdue ? (
              <Badge variant="destructive" className="text-xs">
                Overdue
              </Badge>
            ) : (
              <Badge variant="secondary" className="text-xs">
                On Track
              </Badge>
            )}
            <span className="text-sm font-semibold tabular-nums">
              {Math.round(progress.percentage)}%
            </span>
          </div>
        </div>

        {/* Info row */}
        <div className="flex items-center gap-3 text-xs text-muted-foreground flex-wrap">
          <span className="inline-flex items-center gap-1">
            <Calendar className="w-3 h-3" />
            {formatDate(acceptanceDate)} &rarr; {formatDate(closingDate)}
          </span>
          <span className="inline-flex items-center gap-1">
            <Clock className="w-3 h-3" />
            {progress.totalDays} days total
          </span>
          <span>
            {progress.isOverdue
              ? `${Math.abs(progress.daysLeft)} days overdue`
              : `${progress.daysLeft} days left`}
          </span>
          <span>{formatAmount(deal.amount)}</span>
        </div>

        {/* Progress bar with milestone dots */}
        <div
          className="relative h-3 bg-muted rounded-full"
          role="progressbar"
          aria-valuenow={Math.round(progress.percentage)}
          aria-valuemin={0}
          aria-valuemax={100}
        >
          {firstOverduePosition != null ? (
            <>
              {/* Green fill up to the first overdue milestone */}
              <div
                className="absolute inset-y-0 left-0 rounded-l-full bg-green-500"
                style={{ width: `${firstOverduePosition}%` }}
              />
              {/* Red fill from the first overdue milestone to current progress */}
              <div
                className="absolute inset-y-0 rounded-r-full bg-destructive"
                style={{
                  left: `${firstOverduePosition}%`,
                  width: `${progress.percentage - firstOverduePosition}%`,
                }}
              />
            </>
          ) : (
            <div
              className="absolute inset-y-0 left-0 rounded-full bg-green-500"
              style={{ width: `${progress.percentage}%` }}
            />
          )}
          {enabledMilestones.map((milestone) => (
            <MilestoneDot
              key={milestone.id}
              milestone={milestone}
              acceptanceDate={acceptanceDate}
              closingDate={closingDate}
            />
          ))}
        </div>

        {/* Footer */}
        <div className="flex items-center justify-between text-xs text-muted-foreground">
          <span>
            {enabledMilestones.length > 0
              ? `${completedCount}/${enabledMilestones.length} milestones`
              : "No milestones"}
          </span>
          <div className="flex items-center gap-1.5">
            <span className="text-xs font-medium">
              Day {Math.min(progress.elapsedDays, progress.totalDays)} of{" "}
              {progress.totalDays}
            </span>
            {deal.representation && (
              <Badge variant="outline" className="text-xs capitalize">
                {deal.representation}
              </Badge>
            )}
          </div>
        </div>
      </Card>
    </Link>
  );
};

export const EscrowTimelines = memo(() => {
  const { data, isPending } = useGetList<Deal>("deals", {
    pagination: { perPage: 100, page: 1 },
    sort: { field: "expected_closing_date", order: "ASC" },
    filter: { "stage@in": "(contingency,clear-to-close)" },
  });

  const activeEscrows = useMemo(
    () =>
      (data ?? []).filter((d) => d.acceptance_date && d.expected_closing_date),
    [data],
  );

  if (isPending) return null;

  return (
    <div className="flex flex-col">
      <div className="flex items-center mb-4">
        <div className="mr-3 flex">
          <Briefcase className="text-muted-foreground w-6 h-6" />
        </div>
        <h2 className="text-xl font-semibold text-muted-foreground">
          Active Escrows
        </h2>
        {activeEscrows.length > 0 && (
          <Badge variant="secondary" className="ml-2">
            {activeEscrows.length}
          </Badge>
        )}
      </div>
      {activeEscrows.length === 0 ? (
        <Card className="p-6">
          <p className="text-sm text-muted-foreground text-center">
            No active escrows. Escrows in the Contingency Period or Clear to
            Close stages will appear here.
          </p>
        </Card>
      ) : (
        <div className="flex flex-col gap-3">
          {activeEscrows.map((deal) => (
            <EscrowTimelineCard key={deal.id} deal={deal} />
          ))}
        </div>
      )}
    </div>
  );
});
