import {
  CreateBase,
  Form,
  useGetIdentity,
  useListContext,
  useNotify,
  useRecordContext,
  useResourceContext,
  useDataProvider,
} from "ra-core";
import { useFormContext, useWatch } from "react-hook-form";
import { useEffect } from "react";
import { SaveButton } from "@/components/admin/form";
import { SelectInput } from "@/components/admin/select-input";
import { TextInput } from "@/components/admin/text-input";
import { NumberInput } from "@/components/admin/number-input";
import { DateInput } from "@/components/admin/date-input";
import { ReferenceInput } from "@/components/admin/reference-input";
import { AutocompleteInput } from "@/components/admin/autocomplete-input";
import { BooleanInput } from "@/components/admin/boolean-input";
import { contactOptionText } from "../misc/ContactOption";

const splitContactName = (fullName?: string) => {
  const normalizedName = fullName?.trim().replace(/\s+/g, " ") ?? "";

  if (!normalizedName) {
    return { first_name: "", last_name: "" };
  }

  const [first_name, ...lastNameParts] = normalizedName.split(" ");

  return {
    first_name,
    last_name: lastNameParts.join(" "),
  };
};

export const ListingInquiryCreate = () => {
  const resource = useResourceContext();
  const record = useRecordContext();
  const { identity } = useGetIdentity();

  if (!record || !identity) return null;

  return (
    <CreateBase resource={resource} redirect={false}>
      <Form>
        <ListingInquiryForm listingRecord={record} />
      </Form>
    </CreateBase>
  );
};

const ListingInquiryForm = ({ listingRecord }: { listingRecord: any }) => {
  const { identity } = useGetIdentity();
  const dataProvider = useDataProvider();
  const { setValue } = useFormContext();

  const contactId = useWatch({ name: "contact_id" });

  useEffect(() => {
    if (contactId) {
      dataProvider.getOne("contacts", { id: contactId }).then(({ data }) => {
        setValue(
          "name",
          `${data.first_name || ""} ${data.last_name || ""}`.trim(),
        );
        const email = data.email_jsonb?.[0]?.email;
        if (email) setValue("email", email);
        const phone = data.phone_jsonb?.[0]?.number;
        if (phone) setValue("phone", phone);
      });
    }
  }, [contactId, dataProvider, setValue]);

  return (
    <div className="space-y-4 pt-4 mb-4 border-b pb-6">
      <h3 className="font-semibold text-lg">Add Inquiry or Feedback</h3>
      <div className="flex gap-4">
        <SelectInput
          source="type"
          choices={[
            { id: "Inquiry", name: "Inquiry" },
            { id: "Feedback", name: "Feedback" },
          ]}
          className="w-1/3"
        />
        <TextInput source="name" label="Name" className="flex-1" />
        <div className="flex-1">
          <ReferenceInput source="contact_id" reference="contacts_summary">
            <AutocompleteInput
              optionText={contactOptionText}
              label="Link Contact"
            />
          </ReferenceInput>
        </div>
      </div>
      <div className="flex gap-4">
        <TextInput source="email" className="flex-1" />
        <TextInput source="phone" className="flex-1" />
        <NumberInput source="rating" min={0} max={5} className="w-1/4" />
        <DateInput
          source="date"
          label="Date"
          defaultValue={new Date()}
          className="w-1/4"
        />
      </div>
      <TextInput source="comments" multiline className="w-full" />
      <div className="flex justify-between items-end mt-4">
        <BooleanInput
          source="create_contact"
          label="Add as new Contact"
          helperText={false}
        />
        <ListingInquiryCreateButton
          record={listingRecord}
          identity={identity}
          dataProvider={dataProvider}
        />
      </div>
    </div>
  );
};

const ListingInquiryCreateButton = ({
  record,
  identity,
  dataProvider,
}: {
  record: any;
  identity: any;
  dataProvider: any;
}) => {
  const notify = useNotify();
  const { reset } = useFormContext();
  const { refetch } = useListContext();

  const handleSuccess = () => {
    reset(
      {
        type: "Inquiry",
        name: "",
        email: "",
        phone: "",
        rating: null,
        comments: "",
        contact_id: null,
        create_contact: false,
        date: new Date(),
      },
      { keepValues: false },
    );
    refetch();
    notify("Inquiry added");
  };

  return (
    <div className="flex justify-end">
      <SaveButton
        type="button"
        label="Add Inquiry"
        transform={async (data) => {
          const { create_contact, ...inquiryData } = data;
          let contact_id = data.contact_id;
          if (!contact_id && create_contact && data.name) {
            const { first_name, last_name } = splitContactName(data.name);

            // Query or create "Inquiry" tag
            let tagId;
            try {
              const { data: tags } = await dataProvider.getList("tags", {
                filter: { name: "Inquiry" },
                pagination: { page: 1, perPage: 1 },
                sort: { field: "name", order: "ASC" },
              });
              if (tags.length > 0) {
                tagId = tags[0].id;
              } else {
                const { data: newTag } = await dataProvider.create("tags", {
                  data: { name: "Inquiry", color: "#6b7280" },
                });
                tagId = newTag.id;
              }
            } catch (e) {
              console.error("Failed to fetch or create 'Inquiry' tag", e);
            }

            const { data: contact } = await dataProvider.create("contacts", {
              data: {
                first_name: first_name || "",
                last_name: last_name || "",
                email_jsonb: data.email
                  ? [{ email: data.email, type: "Work" }]
                  : undefined,
                phone_jsonb: data.phone
                  ? [{ number: data.phone, type: "Work" }]
                  : undefined,
                first_seen: new Date().toISOString(),
                last_seen: new Date().toISOString(),
                tags: tagId ? [tagId] : [],
              },
            });
            contact_id = contact.id;
          }
          return {
            ...inquiryData,
            contact_id,
            listing_key: record.id,
            sales_id: identity.id,
            date: data.date || new Date().toISOString(),
          };
        }}
        mutationOptions={{
          onSuccess: handleSuccess,
        }}
      />
    </div>
  );
};
