import {
  useDataProvider,
  useListContext,
  useNotify,
  useRecordContext,
} from "ra-core";
import { useState, useMemo, useCallback } from "react";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Checkbox } from "@/components/ui/checkbox";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Plus } from "lucide-react";
import type { ListingMilestone } from "../types";

const categories = [
  "Pre-listing",
  "Launch preparation",
  "Launch",
  "Active listing management",
  "Offer / Negotiation",
  "Pending",
  "Closing",
] as const;

function getMilestoneSuggestions(category: string): string[] {
  switch (category) {
    case "Pre-listing":
      return [
        "Signed listing agreement",
        "Confirm ownership / vesting",
        "Gather seller disclosures",
        "Gather natural hazard / TDS / SPQ",
        "Confirm occupancy status",
        "Confirm preferred showing instructions",
        "Confirm pets / alarms / gate codes",
        "Obtain keys",
        "Verify lock / access plan",
        "Collect utility and property details",
        "Verify square footage, lot size, permits, HOA details",
        "Preliminary title report ordered",
        "Repairs / vendor walk-through completed",
        "Photography scheduled",
        "Videography scheduled",
        "Drone shoot scheduled",
        "Copywriting started",
        "Signage ordered",
        "Lockbox assigned",
        "Seller net sheet prepared",
        "Pricing strategy review completed",
      ];
    case "Launch preparation":
      return [
        "Property cleaned",
        "Staging installed",
        "Repairs completed",
        "Landscaping completed",
        "Photography delivered",
        "Video delivered",
        "Floor plan delivered",
        "Website page created",
        "Property brochure created",
        "Disclosures package assembled",
        "MLS draft prepared",
        "MLS compliance review completed",
        "Coming Soon activated",
        "Sign installed",
        "Lockbox installed",
        "Access instructions confirmed",
        "Syndication settings reviewed",
        "Broker's open scheduled",
        "First public open house scheduled",
        "Email blast prepared",
        "Social campaign prepared",
        "Ad campaign prepared",
        "Neighborhood invite created",
        "Agent-to-agent outreach list prepared",
      ];
    case "Launch":
      return [
        "Listing entered into MLS",
        "Listing published to website",
        "Syndication verified on portals",
        "Email blast sent",
        "Social posts published",
        "Private network notified",
        "Signage verified on site",
        "Brochure / flyers stocked",
        "Showing service activated",
        "Seller notified listing is live",
      ];
    case "Active listing management":
      return [
        "Hold broker's open",
        "Hold weekend open house",
        "Replenish flyers",
        "Review showing traffic",
        "Collect showing feedback",
        "Follow up with interested buyers' agents",
        "Follow up with public leads",
        "Review inquiry volume",
        "Assess marketing performance",
        "Adjust paid promotion",
        "Refresh social posts",
        "Send weekly seller update",
        "Review pricing vs market response",
        "Recommend price adjustment",
        "Renew / update listing photos",
        "Track disclosure requests",
        "Monitor competing inventory",
        "Track offer interest signals",
        "Document seller decisions",
      ];
    case "Offer / Negotiation":
      return [
        "Confirm offer received",
        "Log offer details",
        "Verify proof of funds",
        "Verify lender / preapproval",
        "Send disclosures to interested parties",
        "Counteroffer issued",
        "Offer comparison worksheet prepared",
        "Seller review meeting held",
        "Best-and-final deadline set",
        "Acceptance recorded",
        "Backup offer pursuit",
        "Contingency timeline entered",
      ];
    case "Pending":
      return [
        "Update MLS to pending",
        "Remove open house schedule",
        "Pause marketing campaigns",
        "Remove some public lead prompts if appropriate",
        "Coordinate appraisal access",
        "Coordinate inspection access",
        "Track contingency deadlines",
        "Escrow milestones logged",
        "Seller update cadence maintained",
        "Backup inquiry queue maintained",
      ];
    case "Closing":
      return [
        "Mark sold in MLS",
        "Sign removal",
        "Remove lockbox",
        "Stop ads",
        "Archive listing site",
        "Notify inquiry leads property sold",
        "Request testimonial / review",
        "Request referral",
        "Capture postmortem notes",
        "Archive documents and activity log",
        "Seller closing summary sent",
      ];
    default:
      return [];
  }
}

export const ListingMilestoneCreate = () => {
  const record = useRecordContext();
  const dataProvider = useDataProvider();
  const notify = useNotify();
  const { data: milestones, refetch } = useListContext<ListingMilestone>();

  const [selectedCategory, setSelectedCategory] = useState("Pre-listing");
  const [checkedMilestones, setCheckedMilestones] = useState<Set<string>>(
    new Set(),
  );
  const [customName, setCustomName] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);

  const existingNames = useMemo(() => {
    if (!milestones) return new Set<string>();
    return new Set(
      milestones
        .filter((m) => m.category === selectedCategory)
        .map((m) => m.milestone_name),
    );
  }, [milestones, selectedCategory]);

  const availableSuggestions = useMemo(() => {
    return getMilestoneSuggestions(selectedCategory).filter(
      (name) => !existingNames.has(name),
    );
  }, [selectedCategory, existingNames]);

  const handleCategoryChange = useCallback((value: string) => {
    setSelectedCategory(value);
    setCheckedMilestones(new Set());
  }, []);

  const toggleCheck = useCallback((name: string) => {
    setCheckedMilestones((prev) => {
      const next = new Set(prev);
      if (next.has(name)) {
        next.delete(name);
      } else {
        next.add(name);
      }
      return next;
    });
  }, []);

  const toggleAll = useCallback(() => {
    if (checkedMilestones.size === availableSuggestions.length) {
      setCheckedMilestones(new Set());
    } else {
      setCheckedMilestones(new Set(availableSuggestions));
    }
  }, [checkedMilestones.size, availableSuggestions]);

  const handleBatchAdd = useCallback(async () => {
    if (!record || checkedMilestones.size === 0) return;
    setIsSubmitting(true);
    try {
      await Promise.all(
        Array.from(checkedMilestones).map((name) =>
          dataProvider.create("listing_milestones", {
            data: {
              listing_key: record.id,
              milestone_name: name,
              category: selectedCategory,
              is_completed: false,
            },
          }),
        ),
      );
      setCheckedMilestones(new Set());
      refetch();
      notify(`${checkedMilestones.size} milestone(s) added`);
    } catch {
      notify("Failed to add milestones", { type: "error" });
    } finally {
      setIsSubmitting(false);
    }
  }, [
    record,
    checkedMilestones,
    selectedCategory,
    dataProvider,
    refetch,
    notify,
  ]);

  const handleCustomAdd = useCallback(async () => {
    const trimmed = customName.trim();
    if (!record || !trimmed) return;
    setIsSubmitting(true);
    try {
      await dataProvider.create("listing_milestones", {
        data: {
          listing_key: record.id,
          milestone_name: trimmed,
          category: selectedCategory,
          is_completed: false,
        },
      });
      setCustomName("");
      refetch();
      notify("Milestone added");
    } catch {
      notify("Failed to add milestone", { type: "error" });
    } finally {
      setIsSubmitting(false);
    }
  }, [record, customName, selectedCategory, dataProvider, refetch, notify]);

  if (!record) return null;

  const allChecked =
    availableSuggestions.length > 0 &&
    checkedMilestones.size === availableSuggestions.length;

  return (
    <div className="space-y-3 pt-4 mb-4 border-b pb-6">
      <div className="flex items-center gap-3 flex-wrap">
        <Select value={selectedCategory} onValueChange={handleCategoryChange}>
          <SelectTrigger className="w-full sm:w-64">
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            {categories.map((cat) => (
              <SelectItem key={cat} value={cat}>
                {cat}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
        {availableSuggestions.length > 0 && (
          <div className="flex items-center gap-2 ml-auto">
            <Button variant="ghost" size="sm" type="button" onClick={toggleAll}>
              {allChecked ? "Deselect all" : "Select all"}
            </Button>
            <Button
              type="button"
              size="sm"
              disabled={checkedMilestones.size === 0 || isSubmitting}
              onClick={handleBatchAdd}
            >
              {isSubmitting
                ? "Adding..."
                : `Add ${checkedMilestones.size} milestone${checkedMilestones.size !== 1 ? "s" : ""}`}
            </Button>
          </div>
        )}
      </div>

      {availableSuggestions.length > 0 ? (
        <div className="max-h-[300px] overflow-y-auto space-y-1 border rounded-md p-3">
          {availableSuggestions.map((name) => (
            <label
              key={name}
              className="flex items-center gap-2 py-1 px-1 rounded hover:bg-muted/50 cursor-pointer text-sm"
            >
              <Checkbox
                checked={checkedMilestones.has(name)}
                onCheckedChange={() => toggleCheck(name)}
              />
              {name}
            </label>
          ))}
        </div>
      ) : (
        <p className="text-sm text-muted-foreground">
          All milestones in this category have been added.
        </p>
      )}

      <div className="flex gap-2">
        <Input
          placeholder="Custom milestone name..."
          value={customName}
          onChange={(e) => setCustomName(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === "Enter") {
              e.preventDefault();
              handleCustomAdd();
            }
          }}
          className="flex-1"
        />
        <Button
          type="button"
          variant="outline"
          size="icon"
          disabled={!customName.trim() || isSubmitting}
          onClick={handleCustomAdd}
        >
          <Plus className="h-4 w-4" />
        </Button>
      </div>
    </div>
  );
};
