import { datatype, lorem, random } from "faker/locale/en_US";
import type { Db } from "./types";
import { randomDate } from "./utils";

export const generateListingNotes = (db: Db) => {
  return Array.from(Array(100).keys()).map((id) => {
    const listing = random.arrayElement(db.listings);
    const sales = random.arrayElement(db.sales);
    return {
      id: id + 1,
      listing_id: listing.id,
      sales_id: sales.id,
      text: lorem.paragraphs(datatype.number({ min: 1, max: 2 })),
      date: randomDate(new Date(listing.created_at)).toISOString(),
    };
  });
};
