import { useRecordContext, useGetList, type Identifier } from "ra-core";
import { Home } from "lucide-react";
import { Link } from "react-router-dom";
import { Badge } from "@/components/ui/badge";

import type { Contact, ListingView } from "../types";

const formatPrice = (price: number | undefined | null) => {
  if (price == null) return "";
  return new Intl.NumberFormat("en-US", {
    style: "currency",
    currency: "USD",
    maximumFractionDigits: 0,
  }).format(price);
};

const statusVariant = (status: string): "default" | "secondary" | "outline" => {
  switch (status?.toLowerCase()) {
    case "active":
      return "default";
    case "pending":
      return "secondary";
    default:
      return "outline";
  }
};

export const ContactListings = () => {
  const record = useRecordContext<Contact>();

  if (!record?.id) return null;

  return <ListingsManager contactId={record.id} />;
};

const ListingsManager = ({ contactId }: { contactId: Identifier }) => {
  const { data: allListings, isPending } = useGetList<ListingView>("listings", {
    pagination: { page: 1, perPage: 1000 },
  });

  if (isPending) {
    return <p className="text-sm text-muted-foreground">Loading...</p>;
  }

  const contactListings =
    allListings?.filter(
      (l) => l.seller_id === contactId || l.contact_ids?.includes(contactId),
    ) || [];

  return (
    <div className="flex flex-col gap-2">
      {contactListings.length > 0 ? (
        <div className="flex flex-col gap-2">
          {contactListings.map((listing) => (
            <div
              key={listing.id}
              className="flex items-start justify-between gap-1 p-2 border rounded-md bg-muted/30"
            >
              <div className="flex flex-col gap-0.5 min-w-0">
                <div className="flex items-center gap-1.5 pl-1">
                  <Home className="w-3.5 h-3.5 text-muted-foreground shrink-0" />
                  <Link
                    to={`/listings/${listing.id}/show`}
                    className="text-sm font-medium underline hover:no-underline text-primary truncate"
                    title={listing.unparsed_address}
                  >
                    {listing.unparsed_address}
                  </Link>
                </div>
                <div className="flex items-center gap-2 pl-5 mt-1">
                  <span className="text-xs text-muted-foreground font-medium">
                    {formatPrice(listing.list_price)}
                  </span>
                  <Badge
                    variant={statusVariant(listing.standard_status)}
                    className="text-[10px] px-1.5 py-0 uppercase tracking-widest"
                  >
                    {listing.standard_status}
                  </Badge>
                </div>
              </div>
            </div>
          ))}
        </div>
      ) : (
        <p className="text-sm text-muted-foreground italic">
          No linked listings
        </p>
      )}
    </div>
  );
};
