import {
  addDays,
  differenceInDays,
  isValid,
  parseISO,
  startOfDay,
  subDays,
} from "date-fns";

import type { EscrowMilestone } from "../types";

/** Parse a date string and normalize to start-of-day in local time */
const parseToLocalDay = (dateStr: string): Date => {
  return startOfDay(parseISO(dateStr));
};

export const calculateMilestoneDate = (
  milestone: EscrowMilestone,
  acceptanceDate?: string,
  closingDate?: string,
): Date | null => {
  if (milestone.date_override) {
    const parsed = parseToLocalDay(milestone.date_override);
    return isValid(parsed) ? parsed : null;
  }

  const refDateStr =
    milestone.reference_point === "acceptance" ? acceptanceDate : closingDate;
  if (!refDateStr) return null;

  const refDate = parseToLocalDay(refDateStr);
  if (!isValid(refDate)) return null;

  if (milestone.reference_point === "closing") {
    return subDays(refDate, Math.abs(milestone.days_offset));
  }
  return addDays(refDate, milestone.days_offset);
};

export const getEscrowProgress = (
  acceptanceDate: string,
  closingDate: string,
  now: Date = new Date(),
) => {
  const start = parseToLocalDay(acceptanceDate);
  const end = parseToLocalDay(closingDate);
  const today = startOfDay(now);
  const totalDays = Math.max(differenceInDays(end, start), 1);
  const elapsedDays = differenceInDays(today, start);
  const daysLeft = totalDays - elapsedDays;
  const isOverdue = daysLeft < 0;
  const percentage = Math.min(
    Math.max((elapsedDays / totalDays) * 100, 0),
    100,
  );

  return { totalDays, elapsedDays, daysLeft, isOverdue, percentage };
};

export const getMilestonePosition = (
  milestoneDate: Date,
  acceptanceDate: string,
  closingDate: string,
): number => {
  const start = parseToLocalDay(acceptanceDate);
  const end = parseToLocalDay(closingDate);
  const totalDays = Math.max(differenceInDays(end, start), 1);
  const milestoneDays = differenceInDays(startOfDay(milestoneDate), start);
  return Math.min(Math.max((milestoneDays / totalDays) * 100, 0), 100);
};

export const getMilestoneStatus = (
  milestone: EscrowMilestone,
  milestoneDate: Date | null,
  now: Date = new Date(),
): "completed" | "overdue" | "upcoming" => {
  if (milestone.completed_at) return "completed";
  if (milestoneDate && startOfDay(milestoneDate) < startOfDay(now))
    return "overdue";
  return "upcoming";
};
