import { generateCompanies } from "./companies";
import { generateContactConnections } from "./contactConnections";
import { generateContactNotes } from "./contactNotes";
import { generateContacts } from "./contacts";
import { generateDealNotes } from "./dealNotes";
import { generateDeals } from "./deals";
import { finalize } from "./finalize";
import { generateHouseholds } from "./households";
import { generateSales } from "./sales";
import { generateTags } from "./tags";
import { generateTasks } from "./tasks";
import { generateListings } from "./listings";
import { generateListingInquiries } from "./listing_inquiries";
import { generateListingMilestones } from "./listing_milestones";
import { generateListingNotes } from "./listing_notes";
import type { Db } from "./types";

export default (): Db => {
  const db = {} as Db;
  db.sales = generateSales(db);
  db.tags = generateTags(db);
  db.companies = generateCompanies(db);
  db.households = generateHouseholds(db);
  db.contacts = generateContacts(db);
  db.contact_connections = generateContactConnections(db);
  db.contact_notes = generateContactNotes(db);
  db.deals = generateDeals(db);
  db.deal_notes = generateDealNotes(db);
  db.tasks = generateTasks(db);
  db.listings = generateListings(db);
  db.listing_inquiries = generateListingInquiries(db);
  db.listing_milestones = generateListingMilestones(db);
  db.listing_notes = generateListingNotes(db);
  db.configuration = [
    {
      id: 1,
      config: {} as Db["configuration"][number]["config"],
    },
  ];
  finalize(db);

  return db;
};
