import { random } from "faker/locale/en_US";

import type { ContactConnection } from "../../../types";
import type { Db } from "./types";

const PREDEFINED_LABELS = ["Parent", "Child", "Sibling", "Spouse", "Friend"];

export const generateContactConnections = (db: Db): ContactConnection[] => {
  const connections: ContactConnection[] = [];
  const existingPairs = new Set<string>();

  // Generate connections - try up to 300 times to get ~100 unique connections
  let attempts = 0;
  while (connections.length < 100 && attempts < 300) {
    attempts++;
    const contactA = random.arrayElement(db.contacts);
    const contactB = random.arrayElement(db.contacts);

    // Skip self-connections
    if (contactA.id === contactB.id) continue;

    // Normalize pair order for uniqueness check (smaller ID first)
    const idA = contactA.id < contactB.id ? contactA.id : contactB.id;
    const idB = contactA.id < contactB.id ? contactB.id : contactA.id;
    const pairKey = `${idA}-${idB}`;

    if (existingPairs.has(pairKey)) continue;
    existingPairs.add(pairKey);

    connections.push({
      id: connections.length,
      contact_id_a: idA,
      contact_id_b: idB,
      label: random.arrayElement(PREDEFINED_LABELS),
      created_at: new Date().toISOString(),
    });
  }

  return connections;
};
